30	export function lerCorpo(argv = process.argv.slice(2), env = process.env, io = { lerArquivo: (p) => readFileSync(p, 'utf8'), gh: ghBody }) {
31	  const iFile = argv.indexOf('--file');
32	  if (iFile >= 0 && argv[iFile + 1]) return { origem: `arquivo ${argv[iFile + 1]}`, body: io.lerArquivo(argv[iFile + 1]) };
33	  const iPr = argv.indexOf('--pr');
34	  if (iPr >= 0 && argv[iPr + 1]) {
35	    const iRepo = argv.indexOf('--repo');
36	    return { origem: `PR #${argv[iPr + 1]}`, body: io.gh(argv[iPr + 1], iRepo >= 0 ? argv[iRepo + 1] : null) };
37	  }
38	  if (typeof env.PR_BODY === 'string') return { origem: 'env PR_BODY', body: env.PR_BODY };
39	  return null;
40	}
