42	function ghBody(n, repo) {
43	  const args = ['pr', 'view', String(n), '--json', 'body', '-q', '.body'];
44	  if (repo) args.push('--repo', repo); // sem --repo, o gh deduz do remote da pasta atual
45	  return execFileSync('gh', args, { encoding: 'utf8' });
46	}
