140	// QUALQUER arquivo sob .githooks/ (o próprio gate de pre-commit não tem extensão).
141	const RE_CODIGO = /\.(?:mjs|cjs|js|jsx|ts|tsx|mts|cts|ps1|psm1|sh|py)$/i;
142	const RE_GITHOOKS = /(?:^|\/)\.githooks\/[^/]+$/;
143	// Mesma convenção de "arquivo de teste" do testes-catraca.mjs (dono único da REGEX é aquele arquivo;
144	// aqui é uma CÓPIA LOCAL — reimplementar é preferível a importar de OUTRO GUARD, que não é lib).
145	const RE_EXT = 'mjs|cjs|js|jsx|ts|tsx|mts|cts';
146	const RE_TESTE = new RegExp(`(?:^|/)(?:[^/]*\\.(?:test|spec|tests|specs)\\.(?:${RE_EXT})|__tests__/(?:[^/]+/)*[^/]*\\.(?:${RE_EXT}))$`, 'i');
147	export const CHANGELOG_PATH = 'CHANGELOG.md';
148	// (achado CU-6) "-"/"*"/"+" (as 3 marcas de lista do CommonMark) OU número seguido de "." ou ")"; o
149	// espaço/tab depois é ASCII de propósito ([ \t], não \s) — fecha o NBSP (achado CU-2, extra) sem casar
150	// por engano um marcador seguido de espaço Unicode que o CommonMark também não reconheceria como lista.
151	const RE_BULLET = /^(?:[-*+]|\d+[.)])[ \t]/;
152	const RE_REF = /#\d+/;
