154	/** FUNÇÃO PURA: <caminho> é código (pra esta regra) — código de verdade, não arquivo de teste. */
155	export function ehCodigoNaoTeste(caminho) {
156	  const p = String(caminho ?? '');
157	  if (RE_TESTE.test(p)) return false;
158	  return RE_CODIGO.test(p) || RE_GITHOOKS.test(p);
159	}
