161	/** FUNÇÃO PURA: <linha> é um bullet de changelog com referência #N? Vê a linha ORIGINAL (não
162	 *  normalizada) — é aqui que um NBSP/espaço Unicode depois do marcador é rejeitado (BANCA INVISÍVEL). */
163	export function ehLinhaBulletComReferencia(linha) {
164	  const l = String(linha ?? '').replace(/\r$/, '').trim();
165	  if (!l) return false;
166	  return RE_BULLET.test(l) && RE_REF.test(l);
167	}
