169	/** FUNÇÃO PURA: chave de comparação de uma linha — trim + colapsa espaço interno. Só serve pra decidir
170	 *  "isto já existia?" (multiset); NUNCA é o texto usado pra julgar se é bullet — essa checagem usa a
171	 *  linha original (ver ehLinhaBulletComReferencia), senão a normalização apagaria a diferença entre um
172	 *  espaço ASCII e um NBSP (reabriria o furo do CU-2/extra). */
173	export function chaveDeComparacao(linha) {
174	  return String(linha ?? '').replace(/\r$/, '').trim().replace(/\s+/g, ' ');
175	}
176	
177	/** FUNÇÃO PURA: <texto> (conteúdo de um CHANGELOG.md) despido de comentário HTML/cerca de código
178	 *  (achado CU-2 — `despirMarkdown` da lib, dono único), quebrado em linhas (\r residual removido). */
179	export function linhasDespidas(texto) {
180	  return despirMarkdown(texto).split('\n').map((l) => l.replace(/\r$/, ''));
181	}
182	
183	/** FUNÇÃO PURA (o coração do conserto do CU-1/CU-3): quais linhas de <headLinhas> são GENUINAMENTE
184	 *  NOVAS — ausentes (por CONTEÚDO normalizado) em <baseLinhas>. MULTISET: uma linha da base só "perdoa"
185	 *  UMA ocorrência igual do lado novo — reordenar ou repetir uma entrada antiga não abre uma segunda
186	 *  vaga. Comparamos CONTEÚDO (o arquivo inteiro nos dois lados), nunca a saída do `git diff` — que
187	 *  reapresenta qualquer linha TOCADA (espaço a mais, reordenada, ou um rename sem `-M` reconhecido) como
188	 *  "+" mesmo sem mudança real (era exatamente o bypass do CU-1). Linha vazia nunca conta (nos dois
189	 *  lados) — não polui o multiset nem "sobra" como nova. */
190	export function linhasGenuinamenteNovas(baseLinhas, headLinhas) {
191	  const restante = new Map();
192	  for (const l of (baseLinhas || [])) {
193	    const k = chaveDeComparacao(l);
194	    if (!k) continue;
195	    restante.set(k, (restante.get(k) || 0) + 1);
196	  }
197	  const novas = [];
198	  for (const l of (headLinhas || [])) {
199	    const k = chaveDeComparacao(l);
200	    if (!k) continue;
201	    const n = restante.get(k) || 0;
202	    if (n > 0) { restante.set(k, n - 1); continue; } // já existia na base — não "empresta" aprovação
203	    novas.push(l); // linha ORIGINAL (não a chave) — preserva NBSP/etc pra ehLinhaBulletComReferencia
204	  }
205	  return novas;
206	}
