208	/** FUNÇÃO PURA: julga o estado coletado. Só cobra CHANGELOG quando há código (fora de teste) no diff. */
209	export function julgar({ arquivosCodigo, changelogTocado, linhasNovas } = {}) {
210	  const codigos = arquivosCodigo || [];
211	  if (codigos.length === 0) return { ok: true, aplicavel: false, problemas: [] };
212	  if (!changelogTocado) {
213	    return {
214	      ok: false, aplicavel: true,
215	      problemas: [{
216	        tipo: 'changelog-ausente',
217	        detalhe: `código mudou (${codigos.length} arquivo(s): ${codigos.slice(0, 3).join(', ')}`
218	          + `${codigos.length > 3 ? ', …' : ''}) mas ${CHANGELOG_PATH} não está no diff`,
219	      }],
220	    };
221	  }
222	  const temRef = (linhasNovas || []).some(ehLinhaBulletComReferencia);
223	  if (!temRef) {
224	    return {
225	      ok: false, aplicavel: true,
226	      problemas: [{
227	        tipo: 'entrada-sem-referencia',
228	        detalhe: `${CHANGELOG_PATH} mudou mas nenhuma linha GENUINAMENTE NOVA (ausente na base) é um bullet`
229	          + ` ("- "/"* "/"+ "/"1. ") com #N (issue/PR)`,
230	      }],
231	    };
232	  }
233	  return { ok: true, aplicavel: true, problemas: [] };
234	}
