236	/** Coleta o estado vs a base (git) e julga. arquivosMudados devolve {path, old} (rename-aware). O
237	 *  confronto do CHANGELOG é merge-base × ÍNDICE (achado CU-3) via conteúdo (achados CU-1/CU-2), nunca
238	 *  via `git diff` da linha do arquivo. */
239	export function medir({ repo, base }) {
240	  const mudados = arquivosMudados(base, repo);
241	  const arquivosCodigo = mudados.filter((e) => ehCodigoNaoTeste(e.path)).map((e) => e.path);
242	  const entradaChangelog = mudados.find((e) => e.path === CHANGELOG_PATH);
243	  const changelogTocado = Boolean(entradaChangelog);
244	  let linhasNovas = [];
245	  if (changelogTocado) {
246	    const mb = git(['merge-base', base, 'HEAD'], repo);
247	    // rename-into (ex.: HISTORY.md → CHANGELOG.md): a "base" do confronto é o CAMINHO ANTIGO, senão o
248	    // conteúdo herdado do arquivo de origem passaria inteiro como "genuinamente novo" (CU-1, A3).
249	    const baseOrigem = entradaChangelog.old || CHANGELOG_PATH;
250	    const baseLinhas = linhasDespidas(conteudoNaBase(mb, baseOrigem, repo));
251	    const headLinhas = linhasDespidas(conteudoNoIndex(CHANGELOG_PATH, repo));
252	    linhasNovas = linhasGenuinamenteNovas(baseLinhas, headLinhas);
253	  }
254	  return { arquivosCodigo, changelogTocado, linhasNovas, julgamento: julgar({ arquivosCodigo, changelogTocado, linhasNovas }) };
255	}
