257	function main() {
258	  const argv = process.argv.slice(2);
259	  const flagBase = (() => { const i = argv.indexOf('--base'); return i >= 0 ? argv[i + 1] : undefined; })();
260	  const repo = repoRaiz(process.cwd());
261	  if (!repo) { console.error(`[${NOME}] NÃO MEDIU: não estou num repositório git.`); process.exitCode = 2; return; }
262	  const base = flagBase || baseDaEsteira(repo);
263	  if (!base) { console.error(`[${NOME}] NÃO MEDIU: informe --base <ref> (ou rode num projeto com esteira.json).`); process.exitCode = 2; return; }
264	  if (!temHead(repo)) { console.log(`[${NOME}] NAO_APLICAVEL: repositório ainda sem commit (primeiro commit).`); process.exitCode = 0; return; }
265	  if (!refExiste(base, repo)) { console.error(`[${NOME}] NÃO MEDIU: a base "${base}" não existe — git fetch primeiro.`); process.exitCode = 2; return; }
266	  let resultado;
267	  try { resultado = medir({ repo, base }); }
268	  catch (e) { console.error(`[${NOME}] NÃO MEDIU: ${e?.message || e}`); process.exitCode = 2; return; }
269	  const { arquivosCodigo, changelogTocado, julgamento } = resultado;
270	  if (!julgamento.aplicavel) { console.log(`[${NOME}] NAO_APLICAVEL: diff vs ${base} não toca código fora de teste.`); process.exitCode = 0; return; }
271	  console.log(
272	    `[${NOME}] base ${base} · ${arquivosCodigo.length} arquivo(s) de código mudado(s) · ${CHANGELOG_PATH} `
273	      + `${changelogTocado ? '' : 'NÃO '}tocado no diff`,
274	  );
275	  if (julgamento.ok) { console.log(`[${NOME}] ✅ ${CHANGELOG_PATH} documenta a mudança com referência (#N).`); process.exitCode = 0; return; }
276	  for (const p of julgamento.problemas) console.error(`[${NOME}] FALHA (${p.tipo}): ${CHANGELOG_PATH} — ${p.detalhe}`);
277	  console.error(
278	    `[${NOME}] COMO PASSAR: adicione uma entrada NOVA em ${CHANGELOG_PATH} (seção [Unreleased], formato Keep a Changelog)`
279	      + ` com um bullet ("- ", "* ", "+ " ou "1. ") citando a issue/PR, ex.: "- corrigido X (#123)".`
280	      + ` Só reordenar/re-tocar uma entrada existente não conta. NUNCA use --no-verify.`,
281	  );
282	  console.error(`[${NOME}] POR QUE EXISTE: PR vencido que muda código sem rastro no CHANGELOG não fica mapeado nem documentado — a mudança some do radar.`);
283	  process.exitCode = 1;
284	}
