90	    return { ok: r.status === 0, saida: ((r.stdout || '') + (r.stderr || '')).trim().split('\n').slice(-6).join('\n') };
91	  }
92	  // Adaptação local (2026-09-11): rotear POR EXTENSÃO, não só pela stack do projeto. Este repositório é
93	  // Python, mas a própria esteira traz um teste Node (tests/esteira.test.mjs). Mandar um `.mjs` para o
94	  // pytest fazia ele coletar zero testes e sair 4 — que o guard traduzia como "pytest não instalado",
95	  // mandando instalar uma ferramenta que não faltava. Agora: `.py` vai para o pytest; o resto, para o
96	  // `node --test`. Reportado ao kit.
97	  const arquivosPy = arquivos.filter((a) => /\.py$/i.test(a));
98	  if (stackPython && arquivosPy.length) {
99	    const py = resolver(cwd);
100	    if (!py) {
101	      return { ferramentaAusente: true, saida: 'python não encontrado (.venv/Scripts, .venv/bin, python, py -3) — instale Python 3.' };
102	    }
103	    const r = spawnSync(py.cmd, [...py.args, '-m', 'pytest', '-q', ...arquivosPy], { cwd, encoding: 'utf8', timeout: 600_000, env: envSemGit() });
104	    const saidaBruta = (r.stdout || '') + (r.stderr || '');
105	    if (r.error || /No module named pytest/i.test(saidaBruta)) {
106	      return { ferramentaAusente: true, saida: `pytest não está instalado nesse Python — rode: ${py.cmd} -m pip install pytest` };
107	    }
108	    // Teste que não é .py no mesmo diff NÃO pode ser pulado em silêncio: roda no node e os dois contam.
109	    const outros = arquivos.filter((a) => !/\.py$/i.test(a));
110	    if (!outros.length) return { ok: r.status === 0, saida: saidaBruta.trim().split('\n').slice(-6).join('\n') };
111	    const rn = spawnSync(process.execPath, ['--test', ...outros], { cwd, encoding: 'utf8', timeout: 600_000, env: envSemGit() });
112	    const saidaNode = ((rn.stdout || '') + (rn.stderr || '')).trim().split('\n').slice(-4).join('\n');
113	    return { ok: r.status === 0 && rn.status === 0, saida: `${saidaBruta.trim().split('\n').slice(-4).join('\n')}\n${saidaNode}` };
114	  }
115	  const r = spawnSync(process.execPath, ['--test', ...arquivos], { cwd, encoding: 'utf8', timeout: 600_000, env: envSemGit() });
116	  return { ok: r.status === 0, saida: ((r.stdout || '') + (r.stderr || '')).trim().split('\n').slice(-6).join('\n') };
117	}
