119	/**
120	 * Mede de verdade: diff base...HEAD (+ index), réplica na base com os testes do HEAD, duas rodadas.
121	 * @returns {{estado, motivo, testes, fontes, saidaBase?, saidaHead?}}
122	 */
123	export function medir({ repo, base, cmd = null, incluirIndex = true } = {}) {
124	  const stackPython = stackDoProjeto(repo) === 'python'; // esteira.json inválido LANÇA → main() trata como NÃO MEDIU
125	  const mergeBase = git(['merge-base', base, 'HEAD'], repo);
126	  const doCommit = git(['diff', '--name-only', `${mergeBase}..HEAD`], repo).split('\n').filter(Boolean);
127	  const doIndex = incluirIndex ? git(['diff', '--name-only', '--cached'], repo).split('\n').filter(Boolean) : [];
128	  const arquivos = [...new Set([...doCommit, ...doIndex])];
129	  const { testes, fontes } = classificarDiff(arquivos, stackPython);
130	  if (testes.length === 0 || fontes.length === 0) return { ...julgar({ testes, fontes }), testes, fontes };
131	
132	  const replica = mkdtempSync(join(tmpdir(), 'crg-'));
133	  try {
134	    git(['worktree', 'add', '--detach', replica, mergeBase], repo);
135	    const nm = join(repo, 'node_modules');
136	    if (existsSync(nm) && !existsSync(join(replica, 'node_modules'))) {
137	      try { execFileSync('cmd', ['/c', 'mklink', '/J', join(replica, 'node_modules'), nm], { stdio: 'ignore' }); } catch { /* ignora-de-proposito: sem junction: o teste roda sem deps */ }
138	    }
139	    for (const t of testes) {
140	      const destino = join(replica, t);
141	      mkdirSync(dirname(destino), { recursive: true });
142	      if (existsSync(join(repo, t))) copyFileSync(join(repo, t), destino);
143	    }
144	    const naBase = rodarTestes(replica, testes, cmd, stackPython);
145	    if (naBase.ferramentaAusente) return { estado: R.FERRAMENTA_AUSENTE, motivo: naBase.saida, testes, fontes };
146	    const noHead = rodarTestes(repo, testes, cmd, stackPython);
147	    if (noHead.ferramentaAusente) return { estado: R.FERRAMENTA_AUSENTE, motivo: noHead.saida, testes, fontes };
148	    const r = julgar({ testes, fontes, vermelhoNaBase: !naBase.ok, verdeNoHead: noHead.ok });
149	    return { ...r, testes, fontes, saidaBase: naBase.saida, saidaHead: noHead.saida };
150	  } finally {
151	    // remove → apaga o que sobrou → prune: se o remove falhar (lock do Windows), o prune
152	    // desregistra a réplica assim que a pasta some. Nunca fica worktree fantasma.
153	    try { git(['worktree', 'remove', '--force', replica], repo); } catch { /* ignora-de-proposito: segue para o rm + prune */ }
154	    try { rmSync(replica, { recursive: true, force: true }); } catch { /* ignora-de-proposito: lock do Windows */ }
155	    try { git(['worktree', 'prune'], repo); } catch { /* ignora-de-proposito: best-effort */ }
156	  }
157	}
