110	/**
111	 * FUNÇÃO PURA: `x` é uma entrada válida de "raiz"/"porModulo"? String não-vazia, sem barra invertida
112	 * (DR-10), sem caminho absoluto (posix ou drive Windows) e sem segmento ".." nem normalização pra raiz
113	 * ("." / "./" / "//") — DR-03: o caminho declarado nunca escapa nem se resolve pra fora da checagem.
114	 */
115	export function entradaValida(x) {
116	  if (typeof x !== 'string') return false;
117	  if (x.trim() === '') return false;
118	  if (x.includes('\\')) return false; // DR-10: caminho declarado é sempre "/", nunca "\"
119	  if (x.startsWith('/')) return false; // DR-03: absoluto (posix)
120	  if (/^[a-zA-Z]:/.test(x)) return false; // DR-03: absoluto (drive Windows, ex. "C:/x")
121	  const semBarraFinal = x.endsWith('/') ? x.slice(0, -1) : x;
122	  const segmentos = semBarraFinal.split('/').filter((s) => s !== '');
123	  if (segmentos.length === 0) return false; // DR-03: normaliza pra vazio/raiz ("/", "//")
124	  if (segmentos.every((s) => s === '.')) return false; // DR-03: "." / "./" normaliza pra raiz
125	  if (segmentos.some((s) => s === '..')) return false; // DR-03: sobe da raiz do projeto (A11)
126	  return true;
