129	/** FUNÇÃO PURA: `texto` tem pelo menos 1 caractere de letra/dígito? DR-04: espaço em branco, BOM,
130	 *  caractere invisível (U+200B, U+2060...) e bytes NUL não contam como conteúdo — só `trim()` não pegava
131	 *  isso; exigir `\p{L}`/`\p{N}` pega qualquer disfarce de vazio, não só os catalogados. */
132	export function temConteudoReal(texto) {
133	  return /[\p{L}\p{N}]/u.test(String(texto ?? ''));
134	}
