136	/**
137	 * FUNÇÃO PURA: julga UMA entrada de "raiz" a partir dos FATOS já medidos (sem fs aqui).
138	 * `caminho` decide PASTA (termina "/") vs ARQUIVO. `fatos`:
139	 *   arquivo → { existe, tamanho, soEspaco, tipoErrado? } · pasta → { existe, qtdArquivos, tipoErrado? }
140	 * Devolve null (ok) ou { tipo: 'doc-ausente' | 'doc-vazio' | 'doc-tipo-errado', caminho, ... }.
141	 * DR-10: quando o nó EXISTE só que com o tipo contrário (pasta declarada como arquivo, ou vice-versa),
142	 * o achado é `doc-tipo-errado` — não a mentira "não existe" de antes.
143	 */
144	export function julgarEntradaRaiz(caminho, fatos) {
145	  const ehPasta = String(caminho ?? '').endsWith('/');
146	  if (!fatos?.existe) {
147	    if (fatos?.tipoErrado) return { tipo: 'doc-tipo-errado', caminho, tipoReal: fatos.tipoErrado, tipoEsperado: ehPasta ? 'pasta' : 'arquivo' };
148	    return { tipo: 'doc-ausente', caminho };
149	  }
150	  if (ehPasta) return (Number(fatos.qtdArquivos) || 0) > 0 ? null : { tipo: 'doc-vazio', caminho };
151	  if (!(Number(fatos.tamanho) > 0) || fatos.soEspaco) return { tipo: 'doc-vazio', caminho };
152	  return null;
153	}
