160	export function julgarArquivoModulo(modulo, arquivo, fatos) {
161	  const caminho = `${modulo}/${arquivo}`;
162	  if (!fatos?.existe || !(Number(fatos.tamanho) > 0) || fatos.soEspaco) return { tipo: 'modulo-sem-doc', caminho };
163	  return null;
164	}
