166	/** Mede um ARQUIVO no disco → fatos para julgarEntradaRaiz/julgarArquivoModulo. SUBSTITUIR: pasta no
167	 *  lugar do arquivo não conta como presente (confere isFile) — e agora diz QUE tipo era (DR-10), em vez
168	 *  de fingir "não existe" quando na verdade existe com o tipo errado. Exportada para o self-test poder
169	 *  exercer o mecanismo real (DR-06: "caso puro" em vez de decoração). */
170	export function medirArquivo(abs) {
171	  let st;
172	  try { st = statSync(abs); } catch { return { existe: false }; }
173	  if (!st.isFile()) return { existe: false, tipoErrado: st.isDirectory() ? 'pasta' : 'outro' };
174	  let buf;
175	  try { buf = readFileSync(abs); } catch { return { existe: false }; }
176	  const tamanho = buf.length;
177	  const soEspaco = tamanho > 0 && !temConteudoReal(buf.toString('utf8')); // DR-04
178	  return { existe: true, tamanho, soEspaco };
179	}
