181	/** Mede uma PASTA no disco → fatos para julgarEntradaRaiz. SUBSTITUIR: arquivo no lugar da pasta não
182	 *  conta como presente (confere isDirectory), com o mesmo `tipoErrado` de medirArquivo (DR-10). DR-05:
183	 *  conta RECURSIVAMENTE — reusa `varrerArvore` (DONO ÚNICO do walker, lib/varredura.mjs — LEI 11), em vez
184	 *  de reimplementar um segundo walker — ignorando `.gitkeep`/`.keep`, e só considera "com conteúdo" o
185	 *  arquivo com ≥1 letra/dígito (mesma régua de medirArquivo — DR-04). */
186	export function medirPasta(abs) {
187	  let st;
188	  try { st = statSync(abs); } catch { return { existe: false }; }
189	  if (!st.isDirectory()) return { existe: false, tipoErrado: st.isFile() ? 'arquivo' : 'outro' };
190	  const { arquivos } = varrerArvore(abs, { aceitar: (nome) => nome !== '.gitkeep' && nome !== '.keep' });
191	  const qtdArquivos = arquivos.filter((a) => temConteudoReal(typeof a.conteudo === 'string' ? a.conteudo : a.conteudo.toString('utf8'))).length;
192	  return { existe: true, qtdArquivos };
