202	function lerConfigValidado(cfgPath) {
203	  const bruto = JSON.parse(readFileSync(cfgPath, 'utf8'));
204	  if (bruto === null || typeof bruto !== 'object' || Array.isArray(bruto)) {
205	    throw new Error(`${cfgPath}: config inválida — não é um objeto JSON.`);
206	  }
207	  for (const chave of Object.keys(bruto)) {
208	    if (!CHAVES_PERMITIDAS.has(chave)) throw new Error(`${cfgPath}: chave desconhecida "${chave}" (permitidas: _doc, raiz, porModulo) — DR-02.`);
209	  }
210	  const raiz = bruto.raiz === undefined ? [] : bruto.raiz;
211	  const porModulo = bruto.porModulo === undefined ? [] : bruto.porModulo;
212	  if (!Array.isArray(raiz)) throw new Error(`${cfgPath}: "raiz" não é uma lista.`);
213	  if (!Array.isArray(porModulo)) throw new Error(`${cfgPath}: "porModulo" não é uma lista.`);
214	  for (const c of raiz) if (!entradaValida(c)) throw new Error(`${cfgPath}: entrada inválida em "raiz" (${JSON.stringify(c)}).`);
215	  for (const a of porModulo) if (!entradaValida(a)) throw new Error(`${cfgPath}: entrada inválida em "porModulo" (${JSON.stringify(a)}).`);
216	  if (raiz.length === 0 && porModulo.length === 0) {
217	    throw new Error(`${cfgPath}: config presente mas não exige NADA de verdade ("raiz" e "porModulo" vazios) — DR-02.`);
218	  }
219	  return { raiz, porModulo };
