222	/**
223	 * Escaneia `dir`. `dir` ilegível → LANÇA (NÃO MEDIU). Sem `governance/DOCS_OBRIGATORIOS.json`:
224	 * projeto da esteira (`<dir>/esteira.json` existe) → achado `config-ausente` (reprovação, DR-01);
225	 * senão → { naoAplicavel: true }. Com config válido → { naoAplicavel: false, achados, modulosMedidos }.
226	 */
227	function escanear(dir) {
228	  let stDir;
229	  try { stDir = statSync(dir); } catch { throw new Error(`--dir ilegível: ${dir}`); }
230	  if (!stDir.isDirectory()) throw new Error(`--dir não é uma pasta: ${dir}`);
231	
232	  const cfgPath = join(dir, 'governance', 'DOCS_OBRIGATORIOS.json');
233	  if (!existsSync(cfgPath)) {
234	    // DR-01: o kit e todo projeto nascido de templates/ trazem esteira.json + o config JUNTOS; se o
235	    // config sumiu num projeto da esteira, é perda de governança (reprovação), não "nunca declarou nada".
236	    if (existsSync(join(dir, 'esteira.json'))) {
237	      return {
238	        naoAplicavel: false,
239	        achados: [{ tipo: 'config-ausente', caminho: 'governance/DOCS_OBRIGATORIOS.json' }],
240	        modulosMedidos: null,
241	        raizModRel: null,
242	      };
243	    }
244	    return { naoAplicavel: true, achados: [], modulosMedidos: null, raizModRel: null };
245	  }
246	
247	  const { raiz, porModulo } = lerConfigValidado(cfgPath); // JSON/shape/chave/vazio-de-verdade inválidos → lança → NÃO MEDIU
248	  const achados = [];
249	
250	  for (const caminho of raiz) {
251	    const abs = join(dir, caminho);
252	    const fatos = caminho.endsWith('/') ? medirPasta(abs) : medirArquivo(abs);
253	    const a = julgarEntradaRaiz(caminho, fatos);
254	    if (a) achados.push(a);
255	  }
256	
257	  let modulosMedidos = null;
258	  let raizModRel = null;
259	  if (porModulo.length > 0) {
260	    const archCfg = lerArchLayers(dir); // DONO ÚNICO de ler .arch-layers.json (scripts/lib/importes.mjs); null se ausente
261	    const raizMod = archCfg?.modulos?.raiz;
262	    if (raizMod) {
263	      raizModRel = raizMod;
264	      const raizModAbs = join(dir, raizMod);
265	      let entradas;
266	      try {
267	        entradas = readdirSync(raizModAbs, { withFileTypes: true });
268	      } catch (e) {
269	        // DR-08: só ENOENT (pasta de módulos ainda não existe — projeto novo) é "0 módulos" legítimo;
270	        // qualquer outro erro (ENOTDIR: é um arquivo; EACCES; etc.) é "não consegui medir" — ERRA ALTO,
271	        // nunca engolido calado no mesmo balde de "projeto sem módulos".
272	        if (e?.code === 'ENOENT') entradas = [];
273	        else throw e;
274	      }
275	      const modDirs = entradas
276	        // DR-07: módulo alcançável só por JUNCTION/SYMLINK não fica invisível — Dirent.isDirectory() não
277	        // segue link; statSync (que segue, comportamento padrão do SO) decide se o alvo é mesmo uma pasta.
278	        .filter((e) => {
279	          if (e.isDirectory()) return true;
280	          if (!e.isSymbolicLink()) return false;
281	          try { return statSync(join(raizModAbs, e.name)).isDirectory(); } catch { return false; }
282	        })
283	        .map((e) => e.name)
284	        // DR-09: a própria arquitetura pode mandar ignorar certas pastas (ex. **/__tests__/**) — reusa o
285	        // DONO ÚNICO (`ignoradoPelaArch`, importes.mjs) em vez de reinventar a checagem (LEI 11).
286	        .filter((nome) => !ignoradoPelaArch(`${raizMod}/${nome}/x`, archCfg));
287	      modulosMedidos = modDirs.length;
288	      for (const modulo of modDirs) {
289	        for (const arquivo of porModulo) {
290	          const a = julgarArquivoModulo(modulo, arquivo, medirArquivo(join(raizModAbs, modulo, arquivo)));
291	          if (a) achados.push(a);
292	        }
293	      }
294	    }
295	    // sem .arch-layers.json ou sem modulos.raiz: NUNCA BLOQUEIA — só "raiz" vale (NÃO é NÃO MEDIU).
296	  }
297	
298	  return { naoAplicavel: false, achados, modulosMedidos, raizModRel };
299	}
