64	import { despirPython } from '../lib/despir-python.mjs';
65	import { RE_TESTE_PY } from '../lib/python-test.mjs';
66	import { paresBaseHead, baseDaEsteira, temHead, refExiste, repoRaiz, envSemGit } from '../lib/git-base.mjs';
