68	const NOME = 'testes-catraca';
69	// Convenção de arquivo de teste JS/TS: sufixo `.test|spec|tests|specs.<ext>` OU qualquer arquivo sob `__tests__/`.
70	const RE_EXT = 'mjs|cjs|js|jsx|ts|tsx|mts|cts';
71	const RE_TESTE = new RegExp(`(?:^|/)(?:[^/]*\\.(?:test|spec|tests|specs)\\.(?:${RE_EXT})|__tests__/(?:[^/]+/)*[^/]*\\.(?:${RE_EXT}))$`, 'i');
72	// RE_TESTE_PY (convenção de teste Python — test_*.py/*_test.py/qualquer .py sob tests/): dono único em
73	// lib/python-test.mjs — companion-red-green.mjs usa a MESMA convenção pra achar o teste a rodar (LEI 11).
74	// Opt-out por-arquivo (idioma do `ignora-de-proposito` do empty-catch): isenta a REDUÇÃO daquele arquivo.
75	// Lido do fonte CRU de propósito — é um comentário; e fica no diff pro auditor validar o motivo.
76	const MARCADOR_OPTOUT = 'catraca-reduz-de-proposito';
77	
78	/** FUNÇÃO PURA: nº de casos de teste (test()/it(), com .only/.skip/.each) no código DESPIDO (JS/TS). */
79	export function contarTestes(fonte) {
80	  return (despirCodigo(String(fonte ?? '')).match(/\b(?:test|it)\b(?:\s*\.\s*\w+)?\s*\(/g) || []).length;
81	}
