83	/** FUNÇÃO PURA (R6, 2026-09-11): nº de casos de teste Python (`def test_…`/`async def test_…`, inclusive
84	 *  método de classe `Test…` — o mesmo token `def test_`, sem caso especial por nome de classe) no código
85	 *  DESPIDO (comentário `#`/string apagados por `despirPython`). */
86	export function contarTestesPython(fonte) {
87	  return (despirPython(String(fonte ?? '')).match(/\bdef\s+test_\w*\s*\(/g) || []).length;
88	}
