90	/** Dispara a contagem certa pra `caminho` (Python vs JS/TS — dono único desta decisão neste guard). */
91	function contarCasos(caminho, fonte) {
92	  return RE_TESTE_PY.test(String(caminho ?? '')) ? contarTestesPython(fonte) : contarTestes(fonte);
93	}
