95	/** FUNÇÃO PURA: o fonte tem o opt-out explícito? (lido no CRU — é um comentário, `//` em JS ou `#` em Python). */
96	export function temOptOut(fonte) {
97	  return String(fonte ?? '').includes(MARCADOR_OPTOUT);
98	}
