100	/** FUNÇÃO PURA: julga cada mudança {arquivo, fonteBase, fonteHead}. Só cobra o que a base já tinha.
101	 *  Por-arquivo de propósito (ver "O QUE NÃO VÊ" (e)). Opt-out `catraca-reduz-de-proposito` no HEAD isenta.
102	 *  A contagem (JS/TS ou Python) é escolhida pelo CAMINHO do arquivo (`contarCasos`). */
103	export function julgar(mudancas) {
104	  const problemas = [];
105	  for (const m of mudancas) {
106	    if (!m.fonteBase) continue; // arquivo de teste novo — nada a catracar
107	    if (temOptOut(m.fonteHead)) continue; // redução declarada e auditável no diff
108	    const cb = contarCasos(m.arquivo, m.fonteBase), ch = contarCasos(m.arquivo, m.fonteHead);
109	    if (cb > 0 && ch < cb) problemas.push({ tipo: 'testes-removidos', arquivo: m.arquivo, detalhe: `casos de teste caíram de ${cb} pra ${ch} (catraca por-arquivo: só cresce; renomear/reescrever pode, reduzir/apagar só com "${MARCADOR_OPTOUT}")` });
110	  }
111	  return { ok: problemas.length === 0, problemas };
112	}
