114	/** Coleta as mudanças de arquivos de teste vs a base (git). paresBaseHead: DONO ÚNICO em lib/git-base.mjs
115	 *  (LEI 11) — teste deletado: head '' → 0 casos → reprova; rename-aware (HOLE 1, via `old`). */
116	export function medir({ repo, base }) {
117	  const mudancas = paresBaseHead(base, repo, (e) => RE_TESTE.test(e.path) || RE_TESTE_PY.test(e.path));
118	  return { mudancas, julgamento: julgar(mudancas) };
119	}
