51	import { ehEntrypoint, selfTestPedido, relatarSelfTest } from '../lib/guard-doctrine.mjs';
52	import { paresBaseHead, baseDaEsteira, temHead, refExiste, repoRaiz, envSemGit } from '../lib/git-base.mjs';
53	import { stackDoProjeto } from '../lib/stack.mjs';
