55	const NOME = 'todo-debt-ratchet';
56	const RE_CODIGO = /\.(?:mjs|cjs|js|jsx|ts|tsx|mts|cts)$/i;
57	const MARCADOR_OPTOUT = 'divida-de-proposito';
58	// Marcador de dívida em CONTEXTO DE COMENTÁRIO: após `//`, `/*`, ou `*` no começo de uma linha jsdoc.
59	// Não-global (testado por-linha). `\b` evita casar TODOList/HACKney etc.
60	const RE_DIVIDA = /(?:\/\/|\/\*|^[ \t]*\*)[ \t]*(?:TODO|FIXME|XXX|HACK)\b/;
61	
62	/** FUNÇÃO PURA: nº de marcadores de dívida NÃO-RASTREADA (sem issue `#\d` nem opt-out) no fonte. Por-linha. */
63	export function contarDividaNaoRastreada(fonte) {
64	  let n = 0;
65	  for (const linha of String(fonte ?? '').split(/\r?\n/)) {
66	    if (!RE_DIVIDA.test(linha)) continue;
67	    if (/#\d+/.test(linha) || linha.includes(MARCADOR_OPTOUT)) continue; // rastreada (issue) ou opt-out explícito
68	    n++;
69	  }
70	  return n;
71	}
72	
73	/** FUNÇÃO PURA: julga cada mudança {arquivo, fonteBase, fonteHead}. Reprova se a dívida CRESCEU vs a base. */
74	export function julgar(mudancas) {
75	  const problemas = [];
76	  for (const m of mudancas) {
77	    const cb = contarDividaNaoRastreada(m.fonteBase), ch = contarDividaNaoRastreada(m.fonteHead);
78	    if (ch > cb) problemas.push({ tipo: 'divida-cresceu', arquivo: m.arquivo, detalhe: `dívida não-rastreada subiu de ${cb} pra ${ch} marcador(es) (TODO/FIXME/XXX/HACK sem issue)` });
79	  }
80	  return { ok: problemas.length === 0, problemas };
81	}
82	
83	/** Coleta as mudanças de arquivos de código vs a base (git). paresBaseHead: DONO ÚNICO em lib/git-base.mjs
84	 *  (LEI 11) — deletado: head '' → 0 (remover dívida é ok); rename-aware (via `old`). */
85	export function medir({ repo, base }) {
86	  const mudancas = paresBaseHead(base, repo, (e) => RE_CODIGO.test(e.path));
87	  return { mudancas, julgamento: julgar(mudancas) };
88	}
