76	const NOME = 'file-loc-ceiling';
77	const PULAR_DIR = new Set(['node_modules', '.git', 'referencia', '.venv', 'venv', '.uv', '__pycache__', 'site-packages']);
78	const EXT_CODIGO = /\.(mjs|cjs|js|jsx|ts|tsx|mts|cts|ps1|py)$/;
79	const TETO_PADRAO = 600; // agora é teto de LINHAS VISUAIS (HOLE 3), não mais de linhas cruas.
80	// ~300KB: fonte escrita à mão fica MUITO abaixo; pega o monólito de 1 linha (minificado/gerado/bundle)
81	// que o teto de linhas não vê (HOLE 1 da auditoria). Configurável por .loc-ceiling.json { tetoBytes }.
82	const TETO_BYTES_PADRAO = 300 * 1024;
83	// largura de revisão (colunas) usada pra converter linhas cruas em VISUAIS. Configurável por
84	// .loc-ceiling.json { largura }, só um inteiro em [80, 400] — ver larguraValida.
85	const LARGURA_PADRAO = 160;
86	
87	/** FUNÇÃO PURA (interna): as linhas CRUAS da fonte, já normalizadas (\r\n, \r e \n contam igual — HOLE
88	 *  2: \r-only não colapsa N linhas em 1). '' → []; ignora um único fim-de-linha final. Base compartilhada
89	 *  de contarLinhas e contarLinhasVisuais: as duas dividem a fonte do MESMO jeito, só divergem em como
90	 *  cada linha vale. */
91	function linhasCruas(fonte) {
92	  const s = String(fonte ?? '').replace(/\r\n?/g, '\n');
93	  if (s === '') return [];
94	  return s.replace(/\n$/, '').split('\n');
95	}
96	
97	/** FUNÇÃO PURA: quantas linhas de conteúdo (cruas) tem a fonte. '' → 0; ignora um único fim-de-linha
98	 *  final. Continua exportada: é a métrica "cru" mostrada ao lado da visual no relatório de falha. */
99	export function contarLinhas(fonte) {
100	  return linhasCruas(fonte).length;
101	}
102	
103	/** FUNÇÃO PURA (HOLE 3 — 2ª rodada da auditoria fria): quantas linhas VISUAIS a fonte ocupa numa
104	 *  revisão de `largura` colunas. Cada linha CRUA conta max(1, ceil(comprimento em CODE POINTS /
105	 *  largura)) — uma linha de 161 colunas com largura 160 conta 2, nunca 1: juntar linhas longas NUNCA
106	 *  economiza teto. `[...linha].length` conta CODE POINTS (não unidades UTF-16) — emoji e acento contam
107	 *  como 1 coluna cada, não 2. Mesma normalização de EOL de contarLinhas (mesma base, linhasCruas). */
108	export function contarLinhasVisuais(fonte, largura) {
109	  const w = Number(largura);
110	  return linhasCruas(fonte).reduce((soma, linha) => soma + Math.max(1, Math.ceil([...linha].length / w)), 0);
111	}
112	
113	/** FUNÇÃO PURA: `largura` é uma política plausível? inteiro em [80, 400] (limites inclusos). Fora disso
114	 *  é ABSURDO (0, negativo, fração, string, um milhão) — desligaria a regra nova sem avisar. Por isso
115	 *  `tetoDe` trata "false" aqui como NÃO MEDIU (lança), nunca como "cai pro padrão" em silêncio. */
116	export function larguraValida(largura) {
117	  const n = Number(largura);
118	  return Number.isInteger(n) && n >= 80 && n <= 400;
119	}
120	
121	/** FUNÇÃO PURA: o arquivo estoura o teto? (compara linhas VISUAIS contra o teto — o chamador decide o
122	 *  que passar aqui.) */
123	export function estouraTeto(nLinhas, teto) {
124	  return Number(nLinhas) > Number(teto);
