127	/** Config efetiva {teto (linhas VISUAIS), tetoBytes, largura}: config do dir < --teto <n> (linhas).
128	 *  Config ILEGÍVEL (sem arquivo, JSON quebrado) → padrões, como sempre. `largura` PRESENTE mas INVÁLIDA
129	 *  (fora de [80, 400] ou não-inteira) é DIFERENTE: não cai pro padrão — lança (NÃO MEDIU no chamador,
130	 *  HOLE 3). Uma largura absurda desligaria a regra nova calada; melhor parar e mandar o dono consertar
131	 *  o config (LEI 2 — não fabrica, não segue calado). */
132	function tetoDe(dir, argv) {
133	  let teto = TETO_PADRAO, tetoBytes = TETO_BYTES_PADRAO, largura = LARGURA_PADRAO;
134	  let cfg = null;
135	  try { cfg = JSON.parse(readFileSync(join(dir, '.loc-ceiling.json'), 'utf8')); }
136	  catch { /* ignora-de-proposito: sem config ou config inválida (JSON quebrado/ausente) → padrões */ }
137	  if (cfg && typeof cfg === 'object') {
138	    const t = Number(cfg.teto); if (Number.isFinite(t) && t > 0) teto = t;
139	    const b = Number(cfg.tetoBytes); if (Number.isFinite(b) && b > 0) tetoBytes = b;
140	    if (cfg.largura !== undefined) {
141	      if (!larguraValida(cfg.largura)) {
142	        throw new Error(`[${NOME}] NÃO MEDIU: "largura" em .loc-ceiling.json precisa ser um inteiro em ` +
143	          `[80, 400] — recebeu ${JSON.stringify(cfg.largura)}.`);
144	      }
145	      largura = Number(cfg.largura);
146	    }
147	  }
148	  const i = argv.indexOf('--teto');
149	  if (i >= 0) { const n = Number(argv[i + 1]); if (Number.isFinite(n) && n > 0) teto = n; }
150	  return { teto, tetoBytes, largura };
