153	// walker + ehBinario: DONO ÚNICO em lib/varredura.mjs. Diferença dos irmãos: aqui o arquivo acima do teto de BYTES
154	// NÃO é pulado calado — é o próprio ACHADO (motivo 'bytes', o monólito de 1 linha da certidão/HOLE 1).
155	// `varrerArvore` bota esse arquivo em `naoMedidos` (o contrato genérico do walker); este guard converte
156	// CADA entrada de `naoMedidos` num achado (re-stat pelo caminho — o valor não muda entre o scan e aqui,
157	// dentro da mesma execução síncrona; erro nessa hora é o mesmo "sumiu no meio" que qualquer outro guard já pula).
158	function escanear(dir, teto, tetoBytes, largura) {
159	  const achados = [];
160	  const { arquivos, naoMedidos } = varrerArvore(dir, { aceitar: (nome) => EXT_CODIGO.test(nome), pular: PULAR_DIR, maxBytes: tetoBytes, comoBuffer: true });
161	  for (const nm of naoMedidos) {
162	    let valor;
163	    try { valor = statSync(nm.caminho).size; } catch { continue; }
164	    achados.push({ arquivo: nm.caminho, motivo: 'bytes', valor, teto: tetoBytes });
165	  }
166	  for (const { caminho, conteudo } of arquivos) {
167	    if (ehBinario(conteudo)) continue;
168	    const texto = conteudo.toString('utf8');
169	    const cruas = contarLinhas(texto);
170	    const visuais = contarLinhasVisuais(texto, largura);
171	    if (estouraTeto(visuais, teto)) achados.push({ arquivo: caminho, motivo: 'linhas', valor: visuais, cruas, teto });
172	  }
173	  return achados;
174	}
