176	export function principal({ argv = process.argv.slice(2), cwd = process.cwd() } = {}) {
177	  const i = argv.indexOf('--dir');
178	  if (i >= 0 && !argv[i + 1]) { console.error(`[${NOME}] NÃO MEDIU: --dir sem caminho.`); return 2; }
179	  const dir = i >= 0 ? argv[i + 1] : cwd;
180	  const { teto, tetoBytes, largura } = tetoDe(dir, argv); // largura absurda no config → lança aqui → rodapé → exit 2
181	  const achados = escanear(dir, teto, tetoBytes, largura); // dir raiz ilegível → lança → rodapé → exit 2
182	  if (achados.length === 0) {
183	    console.log(`[${NOME}] ✅ nenhum arquivo acima do teto (${teto} linhas visuais / ` +
184	      `${Math.round(tetoBytes / 1024)}KB, largura ${largura}) em ${dir}.`);
185	    return 0;
186	  }
187	  for (const a of achados) console.error(a.motivo === 'bytes'
188	    ? `[${NOME}] FALHA: ${a.arquivo} tem ${a.valor} bytes (teto ${a.teto}) — grande demais pra revisar (minificado/gerado?).`
189	    : `[${NOME}] FALHA: ${a.arquivo} tem ${a.cruas} linhas cruas (${a.valor} visuais, teto ${a.teto} visuais, ` +
190	      `largura ${largura}) — quebre as linhas longas ou divida o arquivo: juntar linhas não economiza.`);
191	  console.error(`[${NOME}] COMO PASSAR: quebre em módulos de responsabilidade única e evite linhas longas; ` +
192	    `ou ajuste teto/tetoBytes/largura em .loc-ceiling.json (política global, visível no diff).`);
193	  console.error(`[${NOME}] POR QUE EXISTE: arquivo gigante vira monólito irreviewável — bug se esconde no meio; juntar linhas não escapa do teto.`);
194	  return 1;
195	}
