71	const NOME = 'text-encoding';
72	const PULAR_DIR = new Set(['node_modules', '.git', 'referencia', '.venv', 'venv', '.uv', '__pycache__', 'site-packages']);
73	// Teto de tamanho: acima dele o arquivo NÃO é validado, mas vira NÃO MEDIU (exit 2), nunca "✅" calado
74	// (TE-01 da auditoria). 64 MB cobre qualquer fonte/config/doc real; injetável pra o self-test exercitar a porta.
75	const MAX_BYTES = Number(process.env.TEXTENC_MAX_BYTES) || 64 * 1024 * 1024;
76	// Extensões que DEVEM ser UTF-8 (código, config, doc, dados-texto). Allowlist de ESCOPO ("o que é texto"),
