78	const EXT_TEXTO = new Set([
79	  'mjs', 'cjs', 'js', 'jsx', 'ts', 'tsx', 'mts', 'cts', 'json', 'jsonc', 'json5', // JS/TS/JSON
80	  'md', 'markdown', 'mdx', 'txt', 'rst', 'adoc', // doc
81	  'yml', 'yaml', 'toml', 'ini', 'env', 'xml', 'svg', 'html', 'htm', 'css', 'scss', 'less', 'vue', 'svelte', // config/markup/estilo
82	  'py', 'rb', 'go', 'rs', 'java', 'kt', 'kts', 'c', 'h', 'cpp', 'cc', 'hpp', 'cs', 'php', 'swift', 'lua', 'pl', // outras linguagens
83	  'sh', 'bash', 'zsh', 'ps1', 'psm1', 'bat', 'cmd', // scripts
84	  'sql', 'graphql', 'gql', 'proto', // schema/query
85	  'csv', 'tsv', 'properties', 'conf', 'cfg', 'lock', 'gradle', 'dockerignore', 'gitignore', 'gitattributes', 'editorconfig', 'npmrc', 'nvmrc', // dados/config extras
86	]);
87	// Arquivos de TEXTO sem extensão (ou de nome canônico): entram por BASENAME. Cobre o caso pt-BR realista de
88	// um LICENSE/AUTHORS com "José" salvo em CP1252 (TE-02 da auditoria).
89	const BASENAME_TEXTO = new Set([
90	  'LICENSE', 'LICENCE', 'COPYING', 'NOTICE', 'AUTHORS', 'CONTRIBUTORS', 'PATENTS', 'CODEOWNERS',
91	  'README', 'CHANGELOG', 'CHANGES', 'HISTORY', 'TODO', 'Dockerfile', 'Makefile', 'Procfile', 'Vagrantfile', 'Brewfile', 'Gemfile', 'Rakefile',
92	  '.gitignore', '.gitattributes', '.dockerignore', '.editorconfig', '.npmrc', '.nvmrc', '.env', '.prettierrc', '.eslintrc', '.babelrc',
93	]);
94	// Extensões onde o BOM é DEFEITO (quebra shebang/import/JSON.parse). Em .md/.ps1/.yml o BOM é tolerado.
95	const EXT_BOM_PROIBIDO = new Set(['mjs', 'cjs', 'js', 'jsx', 'ts', 'tsx', 'mts', 'cts', 'json', 'jsonc', 'json5']);
96	
97	/** FUNÇÃO PURA: um caminho/nome está no ESCOPO de "arquivo de texto a validar"? (extensão OU basename conhecido). */
98	export function ehArquivoDeTexto(nome) {
99	  const base = String(nome || '').split(/[\\/]/).pop();
100	  if (BASENAME_TEXTO.has(base)) return true;
101	  const e = extname(base).replace(/^\./, '').toLowerCase();
102	  return EXT_TEXTO.has(e);
103	}
104	
105	const ehBOM = (buf) => buf.length >= 3 && buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF;
106	
107	/**
108	 * FUNÇÃO PURA: offset do primeiro byte que NÃO forma UTF-8 válido, ou -1 se tudo válido. Pula o BOM
109	 * inicial (o BOM é reportado à parte por `ehBOM`, não é "inválido"). Rejeita: continuação solta,
110	 * overlong (C0/C1, E0<A0, F0<90), surrogate (ED>9F), fora do range (F5-FF, F4>8F) e truncado.
111	 */
112	export function primeiroByteInvalidoUtf8(buf) {
113	  const n = buf.length;
114	  let i = ehBOM(buf) ? 3 : 0;
115	  while (i < n) {
116	    const b = buf[i];
117	    if (b < 0x80) { i++; continue; } // ASCII
118	    let extra;
119	    if (b >= 0xC2 && b <= 0xDF) extra = 1;      // 2 bytes (C0/C1 = overlong → cai no else)
120	    else if (b >= 0xE0 && b <= 0xEF) extra = 2; // 3 bytes
121	    else if (b >= 0xF0 && b <= 0xF4) extra = 3; // 4 bytes (até U+10FFFF)
122	    else return i;                              // 80-BF solto, C0/C1, F5-FF
123	    if (i + extra >= n) return i;               // truncado no fim do buffer
124	    const b1 = buf[i + 1];
125	    // faixas do 2º byte (overlong/surrogate/range) — antes de aceitar as continuações genéricas
126	    if (b === 0xE0 && b1 < 0xA0) return i;       // overlong 3-byte
127	    if (b === 0xED && b1 > 0x9F) return i;       // surrogate D800-DFFF
128	    if (b === 0xF0 && b1 < 0x90) return i;       // overlong 4-byte
129	    if (b === 0xF4 && b1 > 0x8F) return i;       // > U+10FFFF
130	    for (let k = 1; k <= extra; k++) {
131	      const c = buf[i + k];
132	      if (c < 0x80 || c > 0xBF) return i + k;    // continuação inválida
133	    }
134	    i += extra + 1;
135	  }
136	  return -1;
137	}
138	
139	/** FUNÇÃO PURA: offset do primeiro byte NUL (0x00), ou -1. */
140	export function primeiroNul(buf) {
141	  for (let i = 0; i < buf.length; i++) if (buf[i] === 0) return i;
142	  return -1;
143	}
144	
145	/** FUNÇÃO PURA: nº da linha (1-based) do byte em `offset` — conta os 0x0A antes dele. */
146	export function linhaDoOffset(buf, offset) {
147	  let linha = 1;
148	  const ate = Math.min(offset, buf.length);
149	  for (let i = 0; i < ate; i++) if (buf[i] === 0x0A) linha++;
150	  return linha;
151	}
152	
153	/** FUNÇÃO PURA: defeitos de encoding de UM arquivo (por NOME p/ escopo + bytes). Sem fs, sem exit. */
154	export function analisar(nome, buf) {
155	  if (!ehArquivoDeTexto(nome)) return []; // fora do escopo (binário/desconhecido/extensão não listada)
156	  const base = String(nome || '').split(/[\\/]/).pop();
157	  const e = extname(base).replace(/^\./, '').toLowerCase();
158	  const achados = [];
159	  const nul = primeiroNul(buf);
160	  if (nul >= 0) { achados.push({ tipo: 'byte-nul', linha: linhaDoOffset(buf, nul) }); return achados; } // binário/UTF-16: um defeito só basta
161	  if (EXT_BOM_PROIBIDO.has(e) && ehBOM(buf)) achados.push({ tipo: 'bom', linha: 1 });
162	  const inv = primeiroByteInvalidoUtf8(buf);
163	  if (inv >= 0) achados.push({ tipo: 'utf8-invalido', linha: linhaDoOffset(buf, inv) });
164	  return achados;
165	}
166	
167	const EXPLICA = {
168	  'byte-nul': 'byte NUL (00) — conteúdo binário/UTF-16 se passando por texto',
169	  'bom': 'BOM (EF BB BF) no início — quebra shebang/import/JSON.parse',
170	  'utf8-invalido': 'byte que não forma UTF-8 válido — arquivo salvo em Latin-1/CP1252?',
171	};
172	
173	// walker: DONO ÚNICO em lib/varredura.mjs. Diferente dos irmãos: aqui `naoMedidos` NÃO é ignorado — é o
174	// TE-01 (arquivo acima do teto não pode sumir calado) e o `principal` abaixo o transforma em NÃO MEDIU
175	// (exit 2), nunca em "✅" silencioso.
176	function escanear(dir) {
177	  return varrerEDetectar(dir, {
178	    aceitar: (nome) => ehArquivoDeTexto(nome), pular: PULAR_DIR, maxBytes: MAX_BYTES,
179	    comoBuffer: true, incluirNaoMedidos: true,
180	    // `analisar` já reduz `nome` ao basename por dentro — pode receber o caminho completo direto.
181	    detector: (conteudo, caminho) => analisar(caminho, conteudo),
182	  });
183	}
184	
185	export function principal({ argv = process.argv.slice(2), cwd = process.cwd() } = {}) {
186	  const i = argv.indexOf('--dir');
187	  if (i >= 0 && !argv[i + 1]) { console.error(`[${NOME}] NÃO MEDIU: --dir sem caminho.`); return 2; }
188	  const dir = i >= 0 ? argv[i + 1] : cwd;
189	  const { achados, naoMedidos } = escanear(dir); // dir raiz ilegível → lança → rodapé → exit 2
190	  if (achados.length) { // defeito achado vence: reprova (1). Arquivos não medidos viram aviso ao lado.
191	    for (const a of achados) console.error(`[${NOME}] FALHA (${a.tipo}): ${a.arquivo}:${a.linha} — ${EXPLICA[a.tipo]}`);
192	    for (const nm of naoMedidos) console.error(`[${NOME}] AVISO (não medido): ${nm.arquivo} — ${nm.motivo}`);
193	    console.error(`[${NOME}] COMO PASSAR: re-salve o arquivo em UTF-8 SEM BOM (VS Code: "Save with Encoding" → "UTF-8"; PowerShell: Set-Content -Encoding utf8NoBOM). Acento e emoji em UTF-8 válido passam de boa.`);
194	    console.error(`[${NOME}] POR QUE EXISTE: byte fora de UTF-8 corrompe acento em silêncio — o parser quebra e o diff fica ilegível.`);
195	    return 1;
196	  }
197	  if (naoMedidos.length) { // nada errado no que li, mas não li tudo → NÃO afirmo "limpo" (doutrina: erra alto, nunca 0)
198	    for (const nm of naoMedidos) console.error(`[${NOME}] NÃO MEDIU: ${nm.arquivo} — ${nm.motivo}. Não posso afirmar "UTF-8 limpo" sobre um arquivo que não li.`);
199	    console.error(`[${NOME}] COMO PASSAR: valide o encoding desse arquivo por fora, ou reduza-o abaixo do teto (env TEXTENC_MAX_BYTES ajusta o teto).`);
200	    return 2;
201	  }
202	  console.log(`[${NOME}] ✅ nenhum defeito de encoding em ${dir} (UTF-8 limpo).`);
203	  return 0;
204	}
