206	// ── fixtures: bytes ruins são MONTADOS por Buffer (nunca literais nesta fonte, senão o guard se auto-acusa) ──
207	const utf8 = (s) => Buffer.from(s, 'utf8');
208	const BOM = Buffer.from([0xEF, 0xBB, 0xBF]);
209	const comBOM = (s) => Buffer.concat([BOM, utf8(s)]);
210	const LATIN1_E_ACUTE = 0xE9;        // 'é' em Latin-1 (byte solto → inválido em UTF-8)
211	const CP1252_ASPA = 0x93;           // aspa curva esquerda em CP1252 (continuação solta em UTF-8)
212	
213	function selfTest() {
214	  const casos = [];
215	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
216	
217	  // ── primeiroByteInvalidoUtf8: aceita UTF-8 válido, rejeita mis-saves ──
218	  check('UTF-8 válido: ASCII → -1', primeiroByteInvalidoUtf8(utf8('const x = 1;\n')) === -1);
219	  check('UTF-8 válido: acentos/travessão/emoji (á é ç — ✅ 𝕏) → -1', primeiroByteInvalidoUtf8(utf8('café — açaí ✅ 𝕏 São João')) === -1);
220	  check('INVÁLIDO: byte Latin-1 é (0xE9) solto → achado no offset', primeiroByteInvalidoUtf8(Buffer.from([0x63, 0x61, 0x66, LATIN1_E_ACUTE, 0x0A])) === 3);
221	  check('INVÁLIDO: continuação solta (CP1252 0x93) → achado', primeiroByteInvalidoUtf8(Buffer.from([0x6F, 0x69, CP1252_ASPA])) === 2);
222	  check('INVÁLIDO: overlong C0 80 → achado no início', primeiroByteInvalidoUtf8(Buffer.from([0xC0, 0x80])) === 0);
223	  check('INVÁLIDO: surrogate ED A0 80 → achado no início', primeiroByteInvalidoUtf8(Buffer.from([0xED, 0xA0, 0x80])) === 0);
224	  check('INVÁLIDO: lead 4-byte fora do range (F5) → achado', primeiroByteInvalidoUtf8(Buffer.from([0xF5, 0x80, 0x80, 0x80])) === 0);
225	  check('INVÁLIDO: multibyte truncado no fim (E2 sozinho) → achado', primeiroByteInvalidoUtf8(Buffer.from([0x61, 0xE2])) === 1);
226	  check('BOM não é "inválido": BOM + ASCII válido → -1 (o BOM é reportado à parte)', primeiroByteInvalidoUtf8(comBOM('const x = 1;')) === -1);
227	  check('VAZIO: buffer vazio → -1', primeiroByteInvalidoUtf8(Buffer.alloc(0)) === -1);
228	
229	  // ── ehBOM / primeiroNul / linhaDoOffset ──
230	  check('ehBOM: com BOM → true; sem → false', ehBOM(comBOM('x')) === true && ehBOM(utf8('x')) === false);
231	  check('primeiroNul: acha o NUL; sem NUL → -1', primeiroNul(Buffer.from([0x61, 0x00, 0x62])) === 1 && primeiroNul(utf8('abc')) === -1);
232	  check('linhaDoOffset: conta as quebras de linha', linhaDoOffset(utf8('a\nb\nX'), 4) === 3);
233	
234	  // ── ehArquivoDeTexto: escopo por extensão OU basename (TE-02) ──
235	  check('ehArquivoDeTexto: extensão listada (a.mjs) e basename conhecido (LICENSE, Dockerfile) → true', ehArquivoDeTexto('src/a.mjs') && ehArquivoDeTexto('LICENSE') && ehArquivoDeTexto('deploy/Dockerfile') && ehArquivoDeTexto('.gitignore'));
236	  check('ehArquivoDeTexto: extensões que o TE-02 pegou (.py .sql .vue .mdx .csv) → true', ['a.py', 'q.sql', 'C.vue', 'doc.mdx', 'dados.csv'].every((n) => ehArquivoDeTexto(n)));
237	  check('ehArquivoDeTexto: binário (.png) e extensão fora da lista (.xyz) e nome qualquer → false', !ehArquivoDeTexto('img.png') && !ehArquivoDeTexto('a.xyz') && !ehArquivoDeTexto('coisa'));
238	
239	  // ── analisar: por NOME (escopo) + bytes ──
240	  check('NUNCA BLOQUEIA: .mjs UTF-8 válido acentuado → 0 achados', analisar('a.mjs', utf8('// ação: valida input\nconst nome = "João";\n')).length === 0);
241	  check('BYPASS: .mjs com byte Latin-1 solto → utf8-invalido', analisar('a.mjs', Buffer.concat([utf8('const s = "caf'), Buffer.from([LATIN1_E_ACUTE]), utf8('";\n')])).some((a) => a.tipo === 'utf8-invalido'));
242	  check('BYPASS: .mjs com BOM → bom', analisar('a.mjs', comBOM('const x = 1;\n')).some((a) => a.tipo === 'bom'));
243	  check('NUNCA BLOQUEIA: .md com BOM → 0 (BOM tolerado fora da família JS/JSON)', analisar('r.md', comBOM('# título\n')).length === 0);
244	  check('BYPASS: .md com byte inválido AINDA reprova (UTF-8 vale em toda extensão de texto)', analisar('r.md', Buffer.concat([utf8('# t'), Buffer.from([LATIN1_E_ACUTE])])).some((a) => a.tipo === 'utf8-invalido'));
245	  check('BYPASS: .json com byte NUL → byte-nul', analisar('p.json', Buffer.from([0x7B, 0x00, 0x7D])).some((a) => a.tipo === 'byte-nul'));
246	  check('BYPASS (TE-02): LICENSE sem extensão com byte Latin-1 → utf8-invalido (entra por basename)', analisar('LICENSE', Buffer.concat([utf8('Copyright Jos'), Buffer.from([LATIN1_E_ACUTE])])).some((a) => a.tipo === 'utf8-invalido'));
247	  check('BYPASS (TE-02): .py com byte Latin-1 → utf8-invalido (extensão de código ampliada)', analisar('s.py', Buffer.concat([utf8('# a'), Buffer.from([LATIN1_E_ACUTE])])).some((a) => a.tipo === 'utf8-invalido'));
248	  check('FORA DO ESCOPO: extensão binária (.png) → 0 (não é lida como texto)', analisar('i.png', Buffer.from([LATIN1_E_ACUTE, 0x00, 0x93])).length === 0);
249	  check('FORA DO ESCOPO (TE-02 declarado): extensão não listada (.xyz) com defeito → 0 (limite conhecido)', analisar('a.xyz', Buffer.from([LATIN1_E_ACUTE])).length === 0);
250	  check('reporta a linha do byte inválido', analisar('a.mjs', Buffer.concat([utf8('linha1\nlinha2\n'), Buffer.from([LATIN1_E_ACUTE])]))[0]?.linha === 3);
251	
252	  // ── PORTA (issue #17): processo real, via --dir em árvores tmp ──
253	  const meu = fileURLToPath(import.meta.url);
254	  const porta = (dir) => spawnSync(process.execPath, [meu, '--dir', dir], { encoding: 'utf8', timeout: 60_000, env: { ...process.env, npm_lifecycle_event: '' } }).status;
255	  const limpo = mkdtempSync(join(tmpdir(), 'te-limpo-'));
256	  const sujo = mkdtempSync(join(tmpdir(), 'te-sujo-'));
257	  try {
258	    writeFileSync(join(limpo, 'ok.mjs'), utf8('// ação e coração em UTF-8 válido ✅\nexport const x = 1;\n'));
259	    writeFileSync(join(limpo, 'nota.png'), Buffer.from([LATIN1_E_ACUTE, 0x00])); // binário por extensão: ignorado
260	    check('PORTA: --dir de árvore limpa (UTF-8 válido, .png ignorado) → exit 0', porta(limpo) === 0);
261	    writeFileSync(join(sujo, 'mau.mjs'), Buffer.concat([utf8('const s = "caf'), Buffer.from([LATIN1_E_ACUTE]), utf8('";\n')]));
262	    check('PORTA: --dir com byte Latin-1 solto → exit 1', porta(sujo) === 1);
263	    check('PORTA: --dir sem caminho → exit 2', spawnSync(process.execPath, [meu, '--dir'], { encoding: 'utf8', env: { ...process.env, npm_lifecycle_event: '' } }).status === 2);
264	    check('PORTA: --dir inexistente → escanear rejeita → rodapé → exit 2', porta(join(sujo, 'nao-existe')) === 2);
265	  } finally { rmSync(limpo, { recursive: true, force: true }); rmSync(sujo, { recursive: true, force: true }); }
266	
267	  // ── PORTA TE-01: arquivo acima do teto NÃO passa calado — vira NÃO MEDIU (exit 2), nunca "✅". Teto injetável. ──
268	  const grande = mkdtempSync(join(tmpdir(), 'te-teto-'));
269	  try {
270	    writeFileSync(join(grande, 'grande.mjs'), utf8('// arquivo de texto VÁLIDO, porém acima do teto injetado no self-test\nexport const x = 1;\n'));
271	    const portaTeto = (env) => spawnSync(process.execPath, [meu, '--dir', grande], { encoding: 'utf8', timeout: 60_000, env: { ...process.env, npm_lifecycle_event: '', ...env } }).status;
272	    check('PORTA (TE-01): arquivo acima do teto → NÃO MEDIU exit 2 (nunca ✅ calado)', portaTeto({ TEXTENC_MAX_BYTES: '8' }) === 2);
273	    check('PORTA (TE-01): o MESMO arquivo, teto padrão → exit 0 (o tamanho é a única causa)', portaTeto({ TEXTENC_MAX_BYTES: '' }) === 0);
274	  } finally { rmSync(grande, { recursive: true, force: true }); }
275	
276	  // ── PORTA: subpasta que é outro checkout git DE VERDADE (.git/ com HEAD) não é varrida ──
277	  const aninha = mkdtempSync(join(tmpdir(), 'te-aninha-'));
278	  try {
279	    mkdirSync(join(aninha, 'sub', '.git'), { recursive: true });
280	    writeFileSync(join(aninha, 'sub', '.git', 'HEAD'), 'ref: refs/heads/main\n');
281	    const mau = Buffer.concat([utf8('const s = "caf'), Buffer.from([LATIN1_E_ACUTE]), utf8('";\n')]);
282	    writeFileSync(join(aninha, 'sub', 'mau.mjs'), mau); // byte Latin-1 solto DENTRO de outro checkout REAL
283	    check('NUNCA BLOQUEIA (checkout real): subpasta com .git/HEAD não é varrida → exit 0', porta(aninha) === 0);
284	    writeFileSync(join(aninha, 'mau.mjs'), mau); // o MESMO arquivo fora de sub/ (sem .git próprio) é varrido normalmente
285	    check('PORTA: o mesmo arquivo fora de sub/ (sem .git) é varrido normalmente → exit 1', porta(aninha) === 1);
286	    // BYPASS (.git falso): troca o checkout REAL por um `.git` arquivo com gitdir pro nada — não esconde nada.
287	    rmSync(join(aninha, 'mau.mjs'), { force: true }); // tira o defeito da raiz: o exit 1 abaixo só pode vir de dentro de sub/
288	    rmSync(join(aninha, 'sub', '.git'), { recursive: true, force: true });
289	    writeFileSync(join(aninha, 'sub', '.git'), 'gitdir: nao-existe\n');
290	    check('BYPASS (.git falso): sub/.git com "gitdir: nao-existe" NÃO esconde a violação → exit 1', porta(aninha) === 1);
291	  } finally { rmSync(aninha, { recursive: true, force: true }); }
292	
293	  process.exitCode = relatarSelfTest(NOME, casos);
294	}
295	
296	if (ehEntrypoint(import.meta.url)) {
297	  if (selfTestPedido()) selfTest();
298	  else { try { process.exitCode = principal(); } catch (e) { console.error(`[${NOME}] NÃO MEDIU: ${e?.message || e}`); process.exitCode = 2; } }
299	}
