53	const NOME = 'minefield';
54	const GUARDS_DIR = dirname(fileURLToPath(import.meta.url));
55	// RAIZ (issue #21): sobe até achar esteira.json (kit OU projeto bootstrapado, scripts/esteira/guards/
56	// incluso); sem esteira.json em lugar nenhum, cai no de sempre (dois níveis acima) — dono único em
57	// ../lib/raiz-do-guard.mjs, usado também por guards-catalog.mjs.
58	const RAIZ = raizDoProjeto(GUARDS_DIR);
