60	/** Env do filho sem GIT_* (hooks do git contaminam repos temporários) e sem passthrough do npm. */
61	function envParaFilho() {
62	  const limpo = Object.fromEntries(Object.entries(process.env).filter(([k]) => !/^GIT_/i.test(k)));
63	  return { ...limpo, npm_lifecycle_event: '' };
64	}
