66	/** Roda `node <guardsDir>/<guard>.mjs --dir <dir>` e devolve o exit code cru (null se o processo nem rodou). */
67	function rodarScanner(guardsDir, guard, dir) {
68	  const r = spawnSync(process.execPath, [join(guardsDir, `${guard}.mjs`), '--dir', dir], { encoding: 'utf8', timeout: 120_000, env: envParaFilho(), windowsHide: true });
69	  return r.status;
70	}
