72	/**
73	 * FUNÇÃO PURA: dado o resultado de cada scanner (exit no limpo, na própria mina, nas alheias), lista os
74	 * problemas. Esperado: limpo=0, própria=1, alheias=0. Qualquer outra coisa é um problema nomeado.
75	 */
76	export function julgar(resultados) {
77	  const problemas = [];
78	  for (const r of resultados) {
79	    if (r.semGuard) { problemas.push({ tipo: 'mina-sem-guard', guard: r.guard, detalhe: `referencia/minado/${r.guard}/ existe mas scripts/guards/${r.guard}.mjs não` }); continue; }
80	    if (r.limpo !== 0) problemas.push({ tipo: r.limpo === 1 ? 'falso-positivo-limpo' : 'erro-no-limpo', guard: r.guard, detalhe: `${r.guard} reprovou/errou a árvore SÃ (exit ${r.limpo}, esperava 0)` });
81	    if (r.propria !== 1) problemas.push({ tipo: r.propria === 0 ? 'nao-morde-propria-mina' : 'erro-na-propria-mina', guard: r.guard, detalhe: `${r.guard} não mordeu a própria mina (exit ${r.propria}, esperava 1)` });
82	    for (const a of (r.alheias || [])) if (a.exit !== 0) problemas.push({ tipo: a.exit === 1 ? 'morde-mina-alheia' : 'erro-na-mina-alheia', guard: r.guard, detalhe: `${r.guard} reagiu à mina de ${a.guard} (exit ${a.exit}, esperava 0)` });
83	  }
84	  return { ok: problemas.length === 0, problemas };
85	}
