87	/**
88	 * Roda o campo minado real. `referenciaRoot`/`guardsDir` injetáveis (o self-test aponta pra árvores tmp).
89	 * Lança se houver mina mas faltar a árvore `limpo` (NÃO MEDIU → o rodapé sai 2).
90	 */
91	export function medir({ referenciaRoot, guardsDir }) {
92	  const minadoRoot = join(referenciaRoot, 'minado');
93	  const limpo = join(referenciaRoot, 'limpo');
94	  if (!existsSync(minadoRoot)) return { resultados: [], count: 0 };
95	  const guards = readdirSync(minadoRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
96	  if (guards.length === 0) return { resultados: [], count: 0 };
97	  if (!existsSync(limpo)) throw new Error(`referencia/limpo ausente — sem árvore SÃ pra baseline dos scanners`);
98	  const resultados = guards.map((g) => {
99	    if (!existsSync(join(guardsDir, `${g}.mjs`))) return { guard: g, semGuard: true };
100	    const limpoExit = rodarScanner(guardsDir, g, limpo);
101	    const propria = rodarScanner(guardsDir, g, join(minadoRoot, g));
102	    const alheias = guards.filter((h) => h !== g).map((h) => ({ guard: h, exit: rodarScanner(guardsDir, g, join(minadoRoot, h)) }));
103	    return { guard: g, limpo: limpoExit, propria, alheias };
104	  });
105	  return { resultados, count: guards.length };
106	}
