108	export function principal({ env = process.env } = {}) {
109	  const referenciaRoot = env.MINEFIELD_REFERENCIA || join(RAIZ, 'referencia');
110	  const guardsDir = env.MINEFIELD_GUARDS || GUARDS_DIR;
111	  const { resultados, count } = medir({ referenciaRoot, guardsDir }); // lança se limpo faltar → rodapé → 2
112	  if (count === 0) { console.log(`[${NOME}] 0 scanners no campo minado (referencia/minado vazio) — pronto, nada a gatear ainda.`); return 0; }
113	  const r = julgar(resultados);
114	  if (r.ok) { console.log(`[${NOME}] ✅ ${count} scanner(s): cada um passa no limpo e morde SÓ a própria mina.`); return 0; }
115	  for (const p of r.problemas) console.error(`[${NOME}] FALHA (${p.tipo}): ${p.detalhe}`);
116	  console.error(`[${NOME}] COMO PASSAR: o scanner tem que sair 0 em referencia/limpo, 1 em referencia/minado/<ele>, e 0 nas minas alheias.`);
117	  console.error(`[${NOME}] POR QUE EXISTE: self-test verde não prova que o guard morde CÓDIGO real nem que fica quieto no são.`);
118	  return 1;
119	}
