121	// ── fixtures da banca: scanners FALSOS que aceitam --dir e reprovam conforme o modo ──
122	function fakeScannerSrc(nome, modo) {
123	  const cond = { honesto: `files.includes('MINA-${nome}')`, nunca: 'false', sempre: 'true', guloso: `files.some((f) => f.startsWith('MINA-'))` }[modo];
124	  return `#!/usr/bin/env node\nimport { readdirSync } from 'node:fs';\nconst i = process.argv.indexOf('--dir');\nconst files = i >= 0 ? readdirSync(process.argv[i + 1]) : [];\nprocess.exitCode = (${cond}) ? 1 : 0;\n`;
125	}
