127	/** Monta referenciaRoot (limpo/ + minado/<nome>/MINA-<nome>) e guardsDir (<nome>.mjs falsos) e chama fn. */
128	function comCampoMinado(specs, fn) {
129	  const base = mkdtempSync(join(tmpdir(), 'mf-'));
130	  try {
131	    const ref = join(base, 'referencia'); const gdir = join(base, 'guards');
132	    mkdirSync(join(ref, 'limpo'), { recursive: true }); writeFileSync(join(ref, 'limpo', 'ok.txt'), 'nada aqui\n');
133	    mkdirSync(gdir, { recursive: true });
134	    for (const { nome, modo } of specs) {
135	      mkdirSync(join(ref, 'minado', nome), { recursive: true });
136	      writeFileSync(join(ref, 'minado', nome, `MINA-${nome}`), 'x\n');
137	      writeFileSync(join(gdir, `${nome}.mjs`), fakeScannerSrc(nome, modo));
138	    }
139	    return fn({ referenciaRoot: ref, guardsDir: gdir, base });
140	  } finally { rmSync(base, { recursive: true, force: true }); }
141	}
