143	function selfTest() {
144	  const casos = [];
145	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
146	  const normPath = (p) => String(p).replace(/\\/g, '/').replace(/\/+$/, '');
147	
148	  // ── RAIZ do projeto (issue #21): minefield assumia dirname(dirname(GUARDS_DIR)) — só bate no
149	  // layout do KIT. Casos novos (dono único em ../lib/raiz-do-guard.mjs, compartilhado com
150	  // guards-catalog.mjs): kit (esteira.json 2 níveis acima → mesma raiz de antes), bootstrapado
151	  // (scripts/esteira/guards/, esteira.json mais acima → acha a raiz certa) e sem esteira.json em
152	  // lugar nenhum (fallback = comportamento de hoje).
153	  {
154	    const t = mkdtempSync(join(tmpdir(), 'rg-kit-'));
155	    try {
156	      writeFileSync(join(t, 'esteira.json'), '{}');
157	      const guardsDir = join(t, 'scripts', 'guards');
158	      mkdirSync(guardsDir, { recursive: true });
159	      check('RAIZ: layout do kit (esteira.json 2 níveis acima) → mesma raiz de antes', normPath(raizDoProjeto(guardsDir)) === normPath(dirname(dirname(guardsDir))));
160	    } finally { rmSync(t, { recursive: true, force: true }); }
161	  }
162	  {
163	    const t = mkdtempSync(join(tmpdir(), 'rg-boot-'));
164	    try {
165	      writeFileSync(join(t, 'esteira.json'), '{}');
166	      const guardsDir = join(t, 'app', 'scripts', 'esteira', 'guards'); // codigo="app": esteira.json bem mais acima
167	      mkdirSync(guardsDir, { recursive: true });
168	      const r = raizDoProjeto(guardsDir);
169	      check('RAIZ: layout bootstrapado (scripts/esteira/guards/) — acha a raiz certa via esteira.json', normPath(r) === normPath(t) && normPath(r) !== normPath(dirname(dirname(guardsDir))));
170	    } finally { rmSync(t, { recursive: true, force: true }); }
171	  }
172	  {
173	    const t = mkdtempSync(join(tmpdir(), 'rg-sem-'));
174	    try {
175	      const guardsDir = join(t, 'scripts', 'guards'); // sem esteira.json em lugar nenhum
176	      mkdirSync(guardsDir, { recursive: true });
177	      // `finder` fake força "não achei" — determinístico, não depende de %TEMP% estar livre de um
178	      // esteira.json perdido (medido: já não estava, na máquina do dono).
179	      check('RAIZ: sem esteira.json em lugar nenhum → cai no comportamento de hoje (dois níveis acima)', normPath(raizDoProjeto(guardsDir, () => null)) === normPath(dirname(dirname(guardsDir))));
180	    } finally { rmSync(t, { recursive: true, force: true }); }
181	  }
182	  // BYPASS (issue #21, item 3): num projeto bootstrapado `referencia/` nunca é copiado (não é um
183	  // "minado vazio" — a pasta-RAIZ inteira não existe). medir() já tolera isso (existsSync em cascata),
184	  // mas sem este caso ninguém prova: passar um MINEFIELD_REFERENCIA cuja pasta nem existe tem que
185	  // sair 0 com contagem 0, nunca vermelho — trata "referencia/ ausente" igual a "minado/ vazio".
186	  {
187	    const pai = mkdtempSync(join(tmpdir(), 'mf-nao-existe-'));
188	    const semReferencia = join(pai, 'referencia'); // deliberadamente NUNCA criado
189	    try {
190	      const m = medir({ referenciaRoot: semReferencia, guardsDir: GUARDS_DIR });
191	      check('BYPASS (referencia/ ausente, não só minado/ vazio): count 0, nunca lança', m.count === 0 && m.resultados.length === 0);
192	      const st = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 60_000, env: { ...envParaFilho(), MINEFIELD_REFERENCIA: semReferencia, MINEFIELD_GUARDS: GUARDS_DIR } });
193	      check('PORTA (projeto bootstrapado sem referencia/): exit 0, nunca vermelho por pasta ausente', st.status === 0);
194	    } finally { rmSync(pai, { recursive: true, force: true }); }
195	  }
196	
197	  // ── julgar: função pura, todos os modos de falha ──
198	  check('julgar: tudo certo (limpo 0, própria 1, alheia 0) → ok', julgar([{ guard: 'a', limpo: 0, propria: 1, alheias: [{ guard: 'b', exit: 0 }] }]).ok === true);
199	  check('julgar: falso-positivo no limpo → reprova', julgar([{ guard: 'a', limpo: 1, propria: 1, alheias: [] }]).problemas.some((p) => p.tipo === 'falso-positivo-limpo'));
200	  check('julgar: não morde a própria mina → reprova', julgar([{ guard: 'a', limpo: 0, propria: 0, alheias: [] }]).problemas.some((p) => p.tipo === 'nao-morde-propria-mina'));
201	  check('julgar: morde mina alheia → reprova', julgar([{ guard: 'a', limpo: 0, propria: 1, alheias: [{ guard: 'b', exit: 1 }] }]).problemas.some((p) => p.tipo === 'morde-mina-alheia'));
202	  check('julgar: mina sem guard → reprova', julgar([{ guard: 'x', semGuard: true }]).problemas.some((p) => p.tipo === 'mina-sem-guard'));
203	  check('julgar: exit 2 (erro) no limpo/própria não é confundido com bite/pass', (() => { const p = julgar([{ guard: 'a', limpo: 2, propria: 2, alheias: [] }]).problemas; return p.some((x) => x.tipo === 'erro-no-limpo') && p.some((x) => x.tipo === 'erro-na-propria-mina'); })());
204	
205	  // ── medir + julgar end-to-end com scanners FALSOS ──
206	  comCampoMinado([{ nome: 'bom', modo: 'honesto' }], ({ referenciaRoot, guardsDir }) => {
207	    check('CONTROLE: scanner honesto (passa limpo, morde a própria) → ok', julgar(medir({ referenciaRoot, guardsDir }).resultados).ok === true);
208	  });
209	  comCampoMinado([{ nome: 'bom', modo: 'honesto' }, { nome: 'ruim', modo: 'nunca' }], ({ referenciaRoot, guardsDir }) => {
210	    check('BYPASS: scanner que nunca morde → nao-morde-propria-mina', julgar(medir({ referenciaRoot, guardsDir }).resultados).problemas.some((p) => p.tipo === 'nao-morde-propria-mina' && p.guard === 'ruim'));
211	  });
212	  comCampoMinado([{ nome: 'bom', modo: 'honesto' }, { nome: 'fp', modo: 'sempre' }], ({ referenciaRoot, guardsDir }) => {
213	    check('BYPASS: scanner que sempre reprova → falso-positivo-limpo', julgar(medir({ referenciaRoot, guardsDir }).resultados).problemas.some((p) => p.tipo === 'falso-positivo-limpo' && p.guard === 'fp'));
214	  });
215	  comCampoMinado([{ nome: 'bom', modo: 'honesto' }, { nome: 'guloso', modo: 'guloso' }], ({ referenciaRoot, guardsDir }) => {
216	    check('BYPASS: scanner guloso (morde qualquer MINA-) → morde-mina-alheia', julgar(medir({ referenciaRoot, guardsDir }).resultados).problemas.some((p) => p.tipo === 'morde-mina-alheia' && p.guard === 'guloso'));
217	  });
218	
219	  // ── PORTA (issue #17): processo real, via seams MINEFIELD_REFERENCIA / MINEFIELD_GUARDS ──
220	  const meu = fileURLToPath(import.meta.url);
221	  const porta = (env) => spawnSync(process.execPath, [meu], { encoding: 'utf8', timeout: 120_000, env: { ...envParaFilho(), ...env } }).status;
222	  comCampoMinado([{ nome: 'bom', modo: 'honesto' }], ({ referenciaRoot, guardsDir }) => {
223	    check('PORTA: campo minado íntegro → exit 0', porta({ MINEFIELD_REFERENCIA: referenciaRoot, MINEFIELD_GUARDS: guardsDir }) === 0);
224	  });
225	  comCampoMinado([{ nome: 'ruim', modo: 'nunca' }], ({ referenciaRoot, guardsDir }) => {
226	    check('PORTA: scanner que não morde → exit 1', porta({ MINEFIELD_REFERENCIA: referenciaRoot, MINEFIELD_GUARDS: guardsDir }) === 1);
227	  });
228	  // VAZIO: minado vazio → exit 0 com contagem 0
229	  const vazio = mkdtempSync(join(tmpdir(), 'mf-vazio-'));
230	  try {
231	    mkdirSync(join(vazio, 'minado'), { recursive: true }); mkdirSync(join(vazio, 'limpo'), { recursive: true });
232	    check('PORTA VAZIO: minado sem scanner → exit 0 (pronto, nada a gatear)', porta({ MINEFIELD_REFERENCIA: vazio, MINEFIELD_GUARDS: GUARDS_DIR }) === 0);
233	  } finally { rmSync(vazio, { recursive: true, force: true }); }
234	  // NÃO MEDIU: minado com scanner mas SEM limpo → medir lança → rodapé → exit 2
235	  const semLimpo = mkdtempSync(join(tmpdir(), 'mf-sl-'));
236	  try {
237	    mkdirSync(join(semLimpo, 'minado', 'bom'), { recursive: true }); writeFileSync(join(semLimpo, 'minado', 'bom', 'MINA-bom'), 'x\n');
238	    check('PORTA: mina sem árvore SÃ (limpo ausente) → medir rejeita → catch do rodapé → exit 2', porta({ MINEFIELD_REFERENCIA: semLimpo, MINEFIELD_GUARDS: GUARDS_DIR }) === 2);
239	  } finally { rmSync(semLimpo, { recursive: true, force: true }); }
240	
241	  process.exitCode = relatarSelfTest(NOME, casos);
242	}
243	
244	if (ehEntrypoint(import.meta.url)) {
245	  if (selfTestPedido()) selfTest();
246	  else { try { process.exitCode = principal(); } catch (e) { console.error(`[${NOME}] NÃO MEDIU: ${e?.message || e}`); process.exitCode = 2; } }
247	}
