1	#!/usr/bin/env node
2	/**
3	 * ─── INTENÇÃO (certidão de nascimento) ───────────────────────────────────────
4	 * POR QUE EXISTE: "consertar" um guard pode ENFRAQUECÊ-LO sem ninguém ver — apagar casos do self-test
5	 *   pra ele parar de reprovar (LEI 74: o número de casos só cresce), ou gutar a certidão de INTENÇÃO.
6	 *   Um guard enfraquecido é PIOR que ausente: dá confiança falsa. Este meta-guard é a catraca — ao
7	 *   MEXER num guard, o nº de casos não pode cair e a certidão não pode sumir, comparado com a BASE.
8	 *
9	 * O QUE FAZ: pega os guards (scripts/guards/*.mjs) MUDADOS vs a base (git) e, pra cada um que na base
10	 *   TINHA casos/certidão, exige que o HEAD não regrida: nº de `check(` do self-test >= o da base, e a
11	 *   certidão (POR QUE EXISTE + CONTRA-PROVA) ainda presente. Guard NOVO (não existia na base) não tem
12	 *   o que catracar. Conta `check(` sobre o código DESPIDO (comentário/string não contam).
13	 *
14	 * O QUE NUNCA MAIS PODE PASSAR:
15	 *   1. guard editado com MENOS casos de self-test que na base (catraca furada);
16	 *   2. guard editado com a certidão de INTENÇÃO gutada (perdeu POR QUE EXISTE e/ou CONTRA-PROVA).
17	 *
18	 * O QUE ESTE GUARD **NÃO** VÊ: (a) se os casos NOVOS são BONS (mordem de verdade) — isso é a
19	 *   prova-de-vida e o auditor; (b) guard novo (sem base) — só cobra a partir de quando ele existe; (c)
20	 *   enfraquecer a LÓGICA mantendo o nº de casos (trocar uma asserção por `true`) — o `true` literal é
21	 *   pego por leitura/auditoria, não por contagem; (d) libs fora de scripts/guards/ (guard-doctrine,
22	 *   despir) — escopo é a pasta de guards.
23	 *
24	 * MODO DE FALHA JÁ ESCAPADO: 1ª auditoria adversarial: (HOLE 1, alta) `temCertidao` testava as frases no
25	 *   fonte CRU — gutar o cabeçalho e manter "POR QUE EXISTE"/"CONTRA-PROVA" num comentário de linha (ou no
26	 *   fix-hint obrigatório da Parte 6) passava; agora só vale o bloco JSDoc que as contém. (HOLE 2) o runner
27	 *   (run-selftests, NAO_SAO_GUARDS) era catracado como guard → refactor legítimo dele reprovava; excluído.
28	 *   (git-base) `conteudoNaBase` fingia "arquivo novo" em QUALQUER erro do git — agora distingue ausente ×
29	 *   erro transitório (existeNaBase), pra um erro não virar "verde com ferramenta morta".
30	 *
31	 * BANCA — as 10 classes:
32	 *   BANCA: STRING/COMENTÁRIO — TRATADA: `check(` é contado sobre o código DESPIDO, e a certidão é lida do
33	 *     bloco JSDoc (não do fonte cru) — frase em comentário/string/fix-hint não infla nem falsifica.
34	 *   BANCA: IMPORT/PATH — NÃO SE APLICA: opera sobre o diff do git (git-base), não segue import/link.
35	 *   BANCA: BASELINE — NÃO SE APLICA: não há allowlist; a "base" é o commit-base do git, não um arquivo editável.
36	 *   VAZIO/NULO/RENOMEAR/SUBSTITUIR(git mockável)/INVISÍVEL viram casos ou são cobertos pelo repo real do self-test.
37	 *
38	 * CONTRA-PROVA: node scripts/guards/guard-change-ritual.mjs --self-test — monta repo git real com um
39	 *   guard na base e prova: casos caíram → reprova; certidão gutada → reprova; mais casos → ok; guard novo → ok.
40	 * ─────────────────────────────────────────────────────────────────────────────
41	 */
42	import { readFileSync, existsSync, mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'node:fs';
43	import { execFileSync, spawnSync } from 'node:child_process';
44	import { join, dirname, basename } from 'node:path';
45	import { tmpdir } from 'node:os';
46	import { fileURLToPath } from 'node:url';
47	import { ehEntrypoint, selfTestPedido, relatarSelfTest } from '../lib/guard-doctrine.mjs';
48	import { despirCodigo } from '../lib/despir-codigo.mjs';
49	import { paresBaseHead, baseDaEsteira, temHead, refExiste, repoRaiz, envSemGit } from '../lib/git-base.mjs';
50	import { NAO_SAO_GUARDS } from './guards-esperados.mjs';
51	
52	const NOME = 'guard-change-ritual';
53	const GUARDS_DIR = dirname(fileURLToPath(import.meta.url));
54	
55	/** FUNÇÃO PURA: nº de chamadas check() do self-test (sobre o código DESPIDO — comentário/string não contam). */
56	export function contarCasos(fonte) {
