59	/** FUNÇÃO PURA: a certidão de INTENÇÃO (o bloco JSDoc de cabeçalho) está presente e íntegra?
60	 *  HOLE 1 da auditoria: testar as frases no fonte CRU deixava gutar o cabeçalho e manter as frases num
61	 *  comentário de linha ou no fix-hint (`console.error('[x] POR QUE EXISTE: ...')` — que a Parte 6 EXIGE).
62	 *  Só vale o bloco `/** ... *​/` que CONTÉM "POR QUE EXISTE" (o mesmo critério do guards-catalog). */
63	export function temCertidao(fonte) {
64	  const blocos = String(fonte ?? '').match(/\/\*\*[\s\S]*?\*\//g) || [];
