69	/** FUNÇÃO PURA: julga cada mudança {arquivo, fonteBase, fonteHead}. Só cobra o que a BASE já tinha. */
70	export function julgar(mudancas) {
71	  const problemas = [];
72	  for (const m of mudancas) {
73	    if (!m.fonteBase) continue; // guard novo — nada a catracar
74	    const cb = contarCasos(m.fonteBase), ch = contarCasos(m.fonteHead);
75	    if (cb > 0 && ch < cb) problemas.push({ tipo: 'casos-diminuiram', arquivo: m.arquivo, detalhe: `self-test caiu de ${cb} pra ${ch} caso(s) (catraca: só cresce)` });
76	    if (temCertidao(m.fonteBase) && !temCertidao(m.fonteHead)) problemas.push({ tipo: 'certidao-gutada', arquivo: m.arquivo, detalhe: 'a certidão de INTENÇÃO sumiu (falta POR QUE EXISTE e/ou CONTRA-PROVA)' });
77	  }
78	  return { ok: problemas.length === 0, problemas };
