56	const NOME = 'guards-catalog';
57	const GUARDS_DIR = dirname(fileURLToPath(import.meta.url));
58	// RAIZ (issue #21): sobe até achar esteira.json (kit OU projeto bootstrapado, scripts/esteira/guards/
59	// incluso); sem esteira.json em lugar nenhum, cai no de sempre (dois níveis acima) — dono único em
60	// ../lib/raiz-do-guard.mjs, usado também por minefield.mjs.
61	const RAIZ = raizDoProjeto(GUARDS_DIR);
62	const CATALOGO_PADRAO = join(RAIZ, 'governance', 'GUARDS_CATALOG.md');
63	const CABECALHO = '# Catálogo de guards (GERADO — não edite à mão)';
64	const RODAPE = 'Gerado por `guards-catalog.mjs`. Para atualizar: `npm run guards-catalog -- --write`.';
65	
66	/** FUNÇÃO PURA: a 1ª frase do "POR QUE EXISTE" da CERTIDÃO (o 1º bloco de comentário) de um guard. '' se não houver.
67	 *  HOLE A da 1ª auditoria: procurar no arquivo inteiro deixava um "POR QUE EXISTE" solto no CÓDIGO (o fix-hint
68	 *  obrigatório da Parte 6, `console.error('[x] POR QUE EXISTE: ...')`) valer como certidão. Só o cabeçalho conta. */
69	const CAP_RESUMO = 160; // teto de caracteres do resumo (índice conciso; HOLE 3 da 2ª auditoria)
70	export function resumoDaFonte(fonte) {
71	  const texto = String(fonte ?? '');
72	  // A certidão é um bloco JSDoc `/** ... */` (dois asteriscos — a convenção de COMO-CRIAR-GUARD) que
73	  // CONTÉM "POR QUE EXISTE". Não é "o 1º bloco de comentário" (HOLE 1 da 2ª auditoria: um
74	  // `/* eslint-disable */` ou licença viria antes) nem um `/* banner */` de uma estrela que só
75	  // MENCIONA a frase (HOLE 2). A INTEGRIDADE da certidão (todos os campos) é do guard-change-ritual.
76	  const blocos = texto.match(/\/\*\*[\s\S]*?\*\//g) || [];
77	  const cert = blocos.find((b) => /POR QUE EXISTE/.test(b));
78	  if (!cert) return '';
79	  const depois = cert.slice(cert.search(/POR QUE EXISTE/)).replace(/^POR QUE EXISTE[^:]*:/, '').replace(/\*+\/\s*$/, '');
80	  const limpo = depois.split('\n').map((l) => l.replace(/^\s*\*+\s?/, '')).join(' ').replace(/\s+/g, ' ').trim();
81	  if (!limpo) return '';
82	  // 1ª frase: período seguido de MAIÚSCULA ou fim — não corta em "etc."/"#1." antes de minúscula (HOLE C).
83	  const ponto = limpo.search(/\.(\s+[A-ZÀ-Þ]|\s*$)/);
84	  let resumo = (ponto >= 0 ? limpo.slice(0, ponto + 1) : limpo).trim();
85	  // teto de tamanho: quando a "1ª frase" não fecha cedo (período antes de dígito/crase/minúscula), corta na palavra.
86	  if (resumo.length > CAP_RESUMO) resumo = `${resumo.slice(0, CAP_RESUMO).replace(/\s+\S*$/, '').trim()}…`;
87	  return resumo;
88	}
