90	/** FUNÇÃO PURA: o catálogo canônico a partir de [{arquivo, resumo}]. Ordenado por arquivo. */
91	export function gerarCatalogo(entradas) {
92	  const linhas = [...entradas].sort((a, b) => a.arquivo.localeCompare(b.arquivo))
93	    .map((e) => `- \`${e.arquivo}\` — ${e.resumo}`);
94	  return [CABECALHO, '', `${linhas.length} guard(s):`, '', ...linhas, '', RODAPE, ''].join('\n');
