1	/**
2	 * python-runtime.mjs — DONO ÚNICO (LEI 11) de "qual Python roda este projeto?" — usado por
3	 * `companion-red-green.mjs` (roda pytest do teste tocado) e `scripts/python-check.mjs` (roda
4	 * ruff+pytest do projeto inteiro). R6, 2026-09-11 — perfil de stack Python do kit (Namastex).
5	 *
6	 * ORDEM DE RESOLUÇÃO (a mesma nos dois consumidores — dono único, não dois palpites que divergem):
7	 *   1. `<projeto>/.venv/Scripts/python.exe` (venv, Windows)
8	 *   2. `<projeto>/.venv/bin/python` (venv, POSIX)
9	 *   3. `python` no PATH
10	 *   4. `py -3` no PATH (launcher do Windows)
11	 * O primeiro candidato que responde a `--version` com exit 0 vence. Devolve `{ cmd, args }` pronto pra
12	 * `spawnSync(cmd, [...args, ...resto])`, ou `null` se NENHUM candidato respondeu — quem chama trata
13	 * `null` como "ferramenta ausente" (NÃO MEDIU explícito, nunca verde por ausência de ferramenta — LEI DO
14	 * NÃO-CHUTE: sem Python real, não há como afirmar vermelho NEM verde).
15	 */
16	import { existsSync } from 'node:fs';
17	import { join } from 'node:path';
18	import { spawnSync } from 'node:child_process';
19	
20	const CANDIDATOS_VENV = [
21	  ['.venv', 'Scripts', 'python.exe'],
22	  ['.venv', 'bin', 'python'],
23	];
24	
25	/** @param {string} [cwd] raiz do projeto (onde procurar .venv/). @returns {{cmd:string, args:string[]}|null} */
26	export function resolverPython(cwd = process.cwd()) {
27	  const candidatos = [
28	    ...CANDIDATOS_VENV.map((partes) => ({ cmd: join(cwd, ...partes), args: [], ehCaminho: true })),
29	    { cmd: 'python', args: [], ehCaminho: false },
30	    { cmd: 'py', args: ['-3'], ehCaminho: false },
31	  ];
32	  for (const cand of candidatos) {
33	    if (cand.ehCaminho && !existsSync(cand.cmd)) continue; // caminho de venv que não existe: nem tenta
34	    let r;
35	    try { r = spawnSync(cand.cmd, [...cand.args, '--version'], { stdio: 'ignore', timeout: 10_000 }); }
36	    catch { continue; }
37	    if (!r.error && r.status === 0) return { cmd: cand.cmd, args: cand.args };
38	  }
39	  return null;
40	}
