65	 * BANCA — as 10 classes:
66	 *   BANCA: VAZIO — RESERVAS.json ausente → NAO_APLICAVEL (exit 0, projeto que não adotou a reserva
67	 *     ainda); `tipos` vazio/ausente ou JSON inválido → NÃO MEDIU (exit 2, nunca 0, nunca "sem violação").
68	 *   BANCA: STRING/COMENTÁRIO — NÃO SE APLICA: não varre padrão dentro de código-fonte; olha NOME de
69	 *     entrada (readdir) e dado ESTRUTURADO (RESERVAS.json + frontmatter da reserva).
70	 *   BANCA: BASELINE — não há allowlist por-arquivo: todo item numerado no `dir` de um tipo ligado é
71	 *     cobrado; a única forma de "aprovar" é a reserva EXISTIR com slug/número batendo — e isso fica no
72	 *     diff (ver "não vê" (b)).
73	 *   BANCA: IMPORT — NÃO SE APLICA: descoberta é por nome de entrada, não por import/alias/re-export.
74	 *   BANCA: PATH — junction/symlink DENTRO do dir do tipo vira NÃO MEDIU (nunca "sem violação" — RN-12);
75	 *     outro checkout git real não é varrido; `dir` absoluto ou fora do repo também NÃO MEDIU (`dir`
76	 *     relativo que simplesmente ainda não existe — tipo nunca usado — é `itens: []`, NUNCA BLOQUEIA).
77	 *   BANCA: NULO — reserva sem `slug` ou sem `numero` no frontmatter (ou frontmatter ilegível) nunca
78	 *     "bate por acaso": ausente vira string vazia / `null`, que só bateria um item cujo slug/numero
79	 *     TAMBÉM fosse vazio — caso degenerado que a regex do nome já impede.
80	 *   BANCA: RENOMEAR — mover o item numerado pra fora de `dir` tira do escopo (estrutural); mover só a
81	 *     RESERVA sem mover o item vira `sem-reserva` (o item continua exigindo a reserva no lugar certo);
82	 *     mover só o item sem a reserva pode deixar uma reserva ÓRFÃ (status `criado` sem item) — coberto.
83	 *   BANCA: INVISÍVEL — BOM na reserva é removido antes do parse (RN-07); acento no slug é a fronteira
84	 *     DECLARADA em "não vê" (c); maiúscula é coberta pela normalização.
85	 *   BANCA: SUBSTITUIR — NÃO SE APLICA à decisão (`julgar` é função pura, sem I/O); a PORTA é medida com
86	 *     o processo REAL (spawnSync), nunca com mock no lugar do guard.
87	 *
88	 * CONTRA-PROVA: node scripts/guards/reserva-de-numero.mjs --self-test
89	 * ─────────────────────────────────────────────────────────────────────────────
90	 */
91	import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
92	import { join, relative, resolve, isAbsolute } from 'node:path';
93	import { ehEntrypoint, selfTestPedido } from '../lib/guard-doctrine.mjs';
94	import { ehOutroCheckout } from '../lib/git-base.mjs';
95	import {
96	  normalizarSlug, parseFrontmatterReserva, listarItensNumerados, buscarPastasComNome,
97	  dentroDe, normalizarBarra, RE_RESERVA_ARQUIVO,
98	} from '../lib/reservas.mjs';
99	
100	const NOME = 'reserva-de-numero';
101	const NOME_PASTA_MIGRATIONS = 'migrations';
102	const DIR_ADR_CONHECIDO = 'governance/adr';
103	
104	class ErroMedicao extends Error {}
105	
106	function ehDiretorio(p) {
107	  try { return statSync(p).isDirectory(); } catch { return false; }
108	}
109	
110	/** valida o `dir` de um tipo LIGADO: relativo e dentro do repo — senão NÃO MEDIU ([REDIGIDO]: "dir
111	 *  absoluto ou fora do repo = NÃO MEDIU"). NÃO exige que exista: um tipo ligado cuja pasta ainda não foi
112	 *  criada (nenhuma reserva usada ainda) é medido como `itens: []` — lenient, nunca NÃO MEDIU — para não
113	 *  bloquear o projeto que só usa um dos tipos configurados (a pasta `governance/adr`/`migrations`
114	 *  "conhecida" continua cobrada separadamente, pelo CAMINHO configurado, não pela existência). */
115	function dirAbsValidado(dirRepoAbs, tipo, def) {
116	  if (isAbsolute(def.dir)) throw new ErroMedicao(`tipo "${tipo}": "dir" é um caminho absoluto ("${def.dir}").`);
117	  const dirAbs = resolve(dirRepoAbs, def.dir);
118	  if (!dentroDe(dirAbs, dirRepoAbs)) throw new ErroMedicao(`tipo "${tipo}": "dir" ("${def.dir}") sai da árvore do projeto.`);
119	  return dirAbs;
120	}
121	
122	/**
123	 * COLETA (I/O): lê RESERVAS.json e o disco, devolve DADOS PUROS — nenhuma decisão aqui (Parte 2 de
124	 * COMO-CRIAR-GUARD: julgamento fica isolado em `julgar`, sem fs/git/exit).
125	 */
126	export function medir(dir) {
127	  if (!existsSync(dir)) throw new ErroMedicao(`diretório "${dir}" não existe.`);
128	  const configPath = join(dir, 'governance', 'RESERVAS.json');
129	  if (!existsSync(configPath)) return { aplicavel: false };
130	
131	  let config;
132	  try { config = JSON.parse(readFileSync(configPath, 'utf8')); }
133	  catch (e) { throw new ErroMedicao(`governance/RESERVAS.json não é JSON válido (${e?.message || e}).`); }
134	  const semTipos = !config || typeof config.tipos !== 'object' || config.tipos === null
135	    || Object.keys(config.tipos).length === 0;
136	  if (semTipos) throw new ErroMedicao('governance/RESERVAS.json sem "tipos" configurado.');
137	
138	  const dirRepoAbs = resolve(dir);
139	  const entradasTipos = Object.entries(config.tipos);
140	  const dirsLigadosAbs = new Map();
141	  for (const [tipo, def] of entradasTipos) {
142	    if (!def?.dir) continue;
143	    dirsLigadosAbs.set(tipo, dirAbsValidado(dirRepoAbs, tipo, def));
144	  }
145	
146	  const tipos = entradasTipos.map(([tipo, def]) => {
147	    if (!def || !def.dir) return { tipo, ligado: false, dir: def?.dir ?? null, itens: [], reservas: [] };
148	    const dirAbs = dirsLigadosAbs.get(tipo);
149	    const reservasDirAbs = join(dirRepoAbs, 'governance', 'reservas', tipo);
150	    let itens = [];
151	    if (existsSync(dirAbs)) { // pasta ainda não criada (tipo nunca usado) → itens:[], nunca NÃO MEDIU
152	      const pularCaminhos = new Set();
153	      if (def.criarDoModelo) pularCaminhos.add(resolve(dirRepoAbs, def.criarDoModelo)); // RN-C6: molde isento
154	      for (const [outroTipo, outroDirAbs] of dirsLigadosAbs) { // RN-07: não invadir dir de outro tipo aninhado
155	        if (outroTipo !== tipo) pularCaminhos.add(outroDirAbs);
156	      }
157	      const { itens: brutos, naoMedidos } = listarItensNumerados(dirAbs, { pularCaminhos, ehOutroCheckout });
158	      if (naoMedidos.length) {
159	        throw new ErroMedicao(`tipo "${tipo}": ${naoMedidos.map((n) => `${n.motivo} em ${normalizarBarra(relative(dirRepoAbs, n.caminho))}`).join('; ')}.`);
160	      }
161	      itens = brutos.map((it) => {
162	        const reservaPath = join(reservasDirAbs, `${it.numero}.md`);
163	        const reservaExiste = existsSync(reservaPath);
164	        const fm = reservaExiste ? (parseFrontmatterReserva(readFileSync(reservaPath, 'utf8')) || {}) : null;
165	        return {
166	          caminho: normalizarBarra(relative(dirRepoAbs, it.caminhoAbs)), // RN-13: path.relative, não slice
167	          numero: it.numero,
168	          slugArquivo: it.slug,
169	          reservaExiste,
170	          slugReserva: fm ? (fm.slug ?? '') : null,
171	          numeroFrontmatter: fm ? (fm.numero ?? null) : null,
172	        };
173	      });
174	    }
175	    const reservasNomes = existsSync(reservasDirAbs) ? readdirSync(reservasDirAbs) : [];
176	    const reservas = reservasNomes.filter((n) => RE_RESERVA_ARQUIVO.test(n)).map((n) => {
177	      const fm = parseFrontmatterReserva(readFileSync(join(reservasDirAbs, n), 'utf8')) || {};
178	      return { arquivo: n, numero: RE_RESERVA_ARQUIVO.exec(n)[1], status: fm.status ?? null };
179	    });
180	    return { tipo, ligado: true, dir: def.dir, largura: def.largura, padrao: def.padrao, itens, reservas };
181	  });
182	
183	  // RN-05: governance/adr/ existente sem NENHUM tipo ligado apontando exatamente pra ela = reprova.
184	  const adrDirAbs = join(dirRepoAbs, ...DIR_ADR_CONHECIDO.split('/'));
185	  const adrExiste = ehDiretorio(adrDirAbs);
186	  const adrCoberta = [...dirsLigadosAbs.values()].some((p) => resolve(p) === resolve(adrDirAbs));
187	
188	  // RN-06: toda pasta "migrations" achada em QUALQUER nível (fora de node_modules/.git/checkout/
189	  // referencia/) tem que ser o dir de algum tipo ligado — não só os 4 caminhos fixos na raiz.
190	  const migrationsAchadas = buscarPastasComNome(dirRepoAbs, NOME_PASTA_MIGRATIONS, { ehOutroCheckout });
191	  const dirsLigadosAbsSet = new Set([...dirsLigadosAbs.values()].map((p) => resolve(p)));
192	  const migrationsSemCobertura = migrationsAchadas
193	    .filter((p) => !dirsLigadosAbsSet.has(resolve(p)))
194	    .map((p) => normalizarBarra(relative(dirRepoAbs, p)));
195	
196	  return { aplicavel: true, tipos, adr: { existe: adrExiste, coberta: adrCoberta }, migrationsSemCobertura };
197	}
198	
199	/**
200	 * FUNÇÃO PURA: julga os DADOS de `medir` (nunca toca fs/git; não faz `process.exit`).
201	 * @returns {{estado:'NAO_APLICAVEL'|'OK'|'FALHA', falhas:object[]}}
202	 */
203	export function julgar(dados) {
204	  if (!dados || dados.aplicavel !== true) return { estado: 'NAO_APLICAVEL', falhas: [] };
205	  const falhas = [];
206	
207	  for (const t of dados.tipos || []) {
208	    if (!t.ligado) continue;
209	    const porValor = new Map();
210	    for (const item of t.itens || []) {
211	      const valor = Number(item.numero);
212	      if (!porValor.has(valor)) porValor.set(valor, []);
213	      porValor.get(valor).push(item);
214	
215	      if (!item.reservaExiste) {
216	        falhas.push({ tipo: 'sem-reserva', arquivo: item.caminho, detalhe: `numero ${item.numero} sem governance/reservas/${t.tipo}/${item.numero}.md` });
217	        continue;
218	      }
219	      const a = normalizarSlug(item.slugArquivo);
220	      const b = normalizarSlug(item.slugReserva ?? '');
221	      if (a !== b) {
222	        falhas.push({
223	          tipo: 'reserva-diverge', arquivo: item.caminho,
224	          detalhe: `slug do arquivo "${item.slugArquivo}" != slug da reserva "${item.slugReserva ?? ''}"`,
225	        });
226	      }
227	      // RN-13: numero: do frontmatter tem que bater com o número do próprio nome.
228	      if (item.numeroFrontmatter != null && Number(item.numeroFrontmatter) !== valor) {
229	        falhas.push({
230	          tipo: 'numero-diverge', arquivo: item.caminho,
231	          detalhe: `numero do frontmatter "${item.numeroFrontmatter}" != numero do nome "${item.numero}"`,
232	        });
233	      }
234	    }
235	    // RN-02: mesmo VALOR numérico usado por mais de um item (largura fora da identidade).
236	    for (const [valor, grupo] of porValor) {
237	      if (grupo.length > 1) {
238	        falhas.push({
239	          tipo: 'numero-duplicado', arquivo: grupo.map((g) => g.caminho).join(', '),
240	          detalhe: `numero ${valor} usado por ${grupo.length} entradas`,
241	        });
242	      }
243	    }
244	    // RN-02: largura divergente da config (só faz sentido pra padrão sequencial — timestamp é sempre 14).
245	    if (t.padrao !== 'timestamp') {
246	      const larguraEsperada = Number.isFinite(t.largura) ? t.largura : 4;
247	      for (const item of t.itens || []) {
248	        if (item.numero.length !== larguraEsperada) {
249	          falhas.push({
250	            tipo: 'largura-diverge', arquivo: item.caminho,
251	            detalhe: `numero "${item.numero}" tem ${item.numero.length} dígito(s), config exige largura ${larguraEsperada}`,
252	          });
253	        }
254	      }
255	    }
256	    // RN-C8: reserva "criado" sem item correspondente = órfã (ADR apagado/renomeado). "reservado" sem
257	    // item é trabalho em voo — NUNCA BLOQUEIA.
258	    for (const r of t.reservas || []) {
259	      if (r.status !== 'criado') continue;
260	      const existe = (t.itens || []).some((it) => Number(it.numero) === Number(r.numero));
261	      if (!existe) {
262	        falhas.push({
263	          tipo: 'reserva-orfa', arquivo: `governance/reservas/${t.tipo}/${r.arquivo}`,
264	          detalhe: `status "criado" sem item numerado correspondente em ${t.dir}`,
265	        });
266	      }
267	    }
268	  }
269	
270	  if (dados.adr?.existe && !dados.adr?.coberta) {
271	    falhas.push({ tipo: 'adr-dir-sem-tipo', arquivo: DIR_ADR_CONHECIDO, detalhe: 'pasta existe mas nenhum tipo ligado em RESERVAS.json aponta pra ela.' });
272	  }
273	  for (const p of dados.migrationsSemCobertura || []) {
274	    falhas.push({ tipo: 'migrations-sem-reserva', arquivo: p, detalhe: 'pasta de migrations existe mas nenhum tipo ligado aponta pra ela.' });
275	  }
276	
277	  return { estado: falhas.length ? 'FALHA' : 'OK', falhas };
278	}
279	
280	export function principal({ argv = process.argv.slice(2), cwd = process.cwd() } = {}) {
281	  const i = argv.indexOf('--dir');
282	  if (i >= 0 && !argv[i + 1]) { console.error(`[${NOME}] NÃO MEDIU: --dir sem caminho.`); return 2; }
283	  const dir = i >= 0 ? argv[i + 1] : cwd;
284	
285	  const dados = medir(dir); // dir ilegível / RESERVAS.json inválido / dir de tipo ruim → lança → exit 2
286	  const r = julgar(dados);
287	  if (r.estado === 'NAO_APLICAVEL') {
288	    console.log(`[${NOME}] NAO_APLICAVEL: ${dir} não tem governance/RESERVAS.json (projeto sem reserva de número).`);
289	    return 0;
290	  }
291	  if (r.estado === 'OK') {
292	    console.log(`[${NOME}] ✅ toda numeração ligada em ${dir} tem reserva com slug/número batendo.`);
293	    return 0;
294	  }
295	  for (const f of r.falhas) console.error(`[${NOME}] FALHA (${f.tipo}): ${f.detalhe} — ${f.arquivo}`);
296	  console.error(`[${NOME}] COMO PASSAR: rode "npm run adr:nova -- \\"<slug>\\"" (ou "npm run migration:nova -- \\"<slug>\\""`);
297	  console.error(`[${NOME}]   para migration; "node scripts/reservar-numero.mjs <tipo> \\"<slug>\\"" funciona igual, sem o npm) —`);
298	  console.error(`[${NOME}]   nunca crie o arquivo/pasta numerado à mão; se o tipo migration existe mas a`);
299	  console.error(`[${NOME}]   pasta real é outra, corrija "dir" em governance/RESERVAS.json.`);
300	  console.error(`[${NOME}] POR QUE EXISTE: [REDIGIDO] — número reservado antes de criar evita colisão entre`);
301	  console.error(`[${NOME}]   frentes paralelas (1 chat = 1 branch = 1 worktree).`);
302	  return 1;
303	}
