305	// self-test mora em ./selftest/reserva-de-numero.mjs (companion) — regra do coordenador: ≤ 600 linhas
306	// visuais por arquivo. Import dinâmico SEM await no topo (evita "unsettled top-level await" — o
307	// companion importa `julgar`/`medir` de volta DESTE arquivo, e um `await` aqui criaria um ciclo com
308	// top-level await que o Node recusa a resolver). A suíte seta process.exitCode ao ser importada.
309	if (ehEntrypoint(import.meta.url)) {
310	  if (selfTestPedido()) {
311	    import('./selftest/reserva-de-numero.mjs').catch((e) => {
312	      console.error(`[${NOME}] NÃO MEDIU: self-test não rodou: ${e?.message || e}`);
313	      process.exitCode = 2;
314	    });
315	  } else {
316	    try { process.exitCode = principal(); } catch (e) {
317	      console.error(`[${NOME}] NÃO MEDIU: ${e?.message || e}`);
318	      process.exitCode = 2;
319	    }
320	  }
321	}
